import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = np.sum(h)
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(12345)

    best_h = None
    best_c = np.inf

    for N in range(2, 16):
        if time.process_time() > deadline:
            break

        def obj(h):
            return np.max(np.convolve(h, h))

        cons = ({'type': 'eq', 'fun': lambda h: np.sum(h) - 1.0},)
        bounds = [(0.0, 1.0)] * N

        starts = [np.ones(N) / N]
        for _ in range(10):
            starts.append(rng.dirichlet(np.ones(N)))

        for x0 in starts:
            if time.process_time() > deadline:
                break
            try:
                res = minimize(obj, x0, method='SLSQP', bounds=bounds,
                               constraints=cons,
                               options={'maxiter': 500, 'ftol': 1e-12})
                h = np.clip(res.x, 0.0, None)
                if np.sum(h) <= 0:
                    continue
                c = _C(h)
                if c < best_c:
                    best_c = c
                    best_h = h.copy()
            except Exception:
