            best_h = s.copy()
            best_c = _C(best_h)

    # Try SLSQP on several N, warm-starting from the previous best via interpolation.
    Ns = list(range(2, 22))
    for N in Ns:
        if time.process_time() > deadline:
            break

        def obj(h):
            return np.max(np.convolve(h, h))

