        bounds = [(0.0, 1.0)] * N

        starts = []
        if best_h is not None:
            # interpolate best_h to size N
            x_old = (np.arange(len(best_h)) + 0.5) / len(best_h)
            x_new = (np.arange(N) + 0.5) / N
            interp = np.interp(x_new, x_old, best_h)
            if interp.sum() > 0:
                starts.append(interp / interp.sum())
        starts.append(np.ones(N) / N)
        for _ in range(8):
            starts.append(rng.dirichlet(np.ones(N)))

        for x0 in starts:
            if time.process_time() > deadline:
                break
            try:
                res = minimize(obj, x0, method='SLSQP', bounds=bounds,
                               constraints=cons,
                               options={'maxiter': 800, 'ftol': 1e-13})
                h = np.clip(res.x, 0.0, None)
                if np.sum(h) <= 0:
                    continue
                c = _C(h)
                if c < best_c:
                    best_c = c
                    best_h = h.copy()
            except Exception:
                continue

        if best_h is not None:
            print(f"N={N} best C={best_c:.9f}")

    if best_h is None:
        return np.ones(50)

    # Refine further with larger N via multiplicative coordinate ascent.
    h = best_h.astype(float).copy()
    c = best_c
    step = 0.02
    while time.process_time() < deadline:
        N = len(h)
        improved = False
        # try upsampling once if it helps
        for _ in range(30):
            if time.process_time() > deadline:
                break
            trial = h.copy()
            i = rng.integers(0, N)
