        if s.ndim == 1 and s.size > 0 and np.all(s >= 0) and s.sum() > 0:
            best_h = s.copy()
            best_c = _C(s)

    # Direct SLSQP on the true objective (max of convolution) at several N,
    # seeded from the start (upsampled/downsampled) and from smooth bumps.
    def smooth_bump(N, p=1.0):
        x = (np.arange(N) + 0.5) / N
        return np.clip(np.sin(np.pi * x), 0, None) ** p

    def resize(h, N):
        x = np.linspace(0, 1, len(h))
        xn = np.linspace(0, 1, N)
        return np.interp(xn, x, h)

    def obj(h):
        return np.max(np.convolve(h, h))

    Ns = [30, 40, 50, 60, 80, 100, 120, 150]
    for N in Ns:
        if time.process_time() > deadline:
            break
        cons = ({'type': 'eq', 'fun': lambda h: np.sum(h) - 1.0},)
        bounds = [(0.0, 1.0)] * N
        starts = []
        if best_h is not None:
            h0 = resize(best_h, N)
            if h0.sum() > 0:
                starts.append(h0 / h0.sum())
        for p in [0.5, 1.0, 2.0]:
            b = smooth_bump(N, p)
            starts.append(b / b.sum())
        for _ in range(2):
            starts.append(rng.dirichlet(np.ones(N)))

        for x0 in starts:
