from scipy.optimize import linprog


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resample(h, N_target):
    h = np.asarray(h, dtype=float).ravel()
    n = len(h)
    if n == N_target:
        return h.copy()
    # normalized positions of old step centers and new step centers
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N_target) + 0.5) / N_target
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    N_target = 200
    if start is not None:
        h0 = np.asarray(start, dtype=float).ravel()
        if h0.size == 0 or h0.sum() <= 0 or not np.all(np.isfinite(h0)):
            h = np.ones(N_target) / N_target
        else:
            h = _resample(h0, N_target)
    else:
        h = np.ones(N_target) / N_target
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(N_target) / N_target

    best_h = h.copy()
    best_C = _C(h)

    n = len(h)
    max_iter = 40
    for it in range(max_iter):
        if time.process_time() > deadline:
            break

        c = np.convolve(h, h)
        m = len(c)

        A_ub = np.zeros((m, n + 1))
        for k in range(m):
            jlo = max(0, k - (n - 1))
            jhi = min(n - 1, k)
            if jlo <= jhi:
                idx = np.arange(jlo, jhi + 1)
                A_ub[k, idx] = 2.0 * h[k - idx]
            A_ub[k, n] = -1.0
        b_ub = -c

        A_eq = np.zeros((1, n + 1))
        A_eq[0, :n] = 1.0
        b_eq = np.array([0.0])

        bounds = [(-h[j], None) for j in range(n)] + [(0.0, None)]

        obj = np.zeros(n + 1)
        obj[n] = 1.0

        try:
            res = linprog(obj, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                          bounds=bounds, method='highs')
        except Exception:
            break

        if not res.success or res.x is None:
            break

        delta = res.x[:n]
        cur_C = _C(h)
        accepted = False
        step = 1.0
        for _ in range(8):
            cand = h + step * delta
            cand = np.maximum(cand, 0.0)
            if cand.sum() > 0:
                cc = _C(cand)
                if cc < cur_C - 1e-12:
                    h = cand
                    accepted = True
                    break
            step *= 0.5
        if not accepted:
            cand = np.maximum(h + 1e-3 * delta, 0.0)
            if cand.sum() > 0 and _C(cand) < cur_C:
                h = cand
            else:
                break

        cC = _C(h)
        if cC < best_C:
            best_C = cC
            best_h = h.copy()

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(n) / n

    return best_h

