def _expand(z):
    # z: first ceil(N/2) log-heights; build full symmetric log-array
    m = z.size
    # full length N: if N even, N=2m; if odd, N=2m-1 (center shared)
    # We'll treat z as half including center when odd. Determine N from caller.
    raise RuntimeError


def _softmax_obj_half(z, beta, N):
    m = z.size
    if N % 2 == 0:
        # z has N/2 entries; mirror
        zf = np.concatenate([z, z[::-1]])
    else:
        # z has (N+1)/2 entries; center shared
        zf = np.concatenate([z, z[-2::-1]])
    zf = zf - zf.max()
    h = np.exp(zf)
    s = h.sum()
    h = h / s
    c = np.convolve(h, h)
    bc = beta * c
    mx = bc.max()
    w = np.exp(bc - mx)
    sw = w.sum()
    F = (np.log(sw) + mx) / beta
    w = w / sw
    g = np.correlate(w, h, 'valid')
    grad_h = 2.0 * g
    dot = np.dot(h, grad_h)
    grad_full = h * (grad_h - dot)
    # reduce gradient to half-space (sum contributions of mirrored pairs)
    if N % 2 == 0:
        grad = grad_full[:m] + grad_full[::-1][:m]
    else:
        grad = grad_full[:m].copy()
        grad[:-1] += grad_full[::-1][:m - 1]
    return F, grad


def _refine_half(z, beta, N, deadline, maxiter=300):
    if time.process_time() > deadline:
        return z
    try:
        res = minimize(lambda zv: _softmax_obj_half(zv, beta, N), z, jac=True,
                       method='L-BFGS-B',
                       options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13})
    except Exception:
        return z
    if res.x is not None and np.all(np.isfinite(res.x)):
