    xo = (np.arange(n) + 0.5) / n
    xn = (np.arange(N) + 0.5) / N
    return np.interp(xn, xo, h)


def _symmetrize(h):
    return 0.5 * (h + h[::-1])


def _half_from_full(h):
    N = len(h)
    m = (N + 1) // 2
    return h[:m].copy()


def _full_from_half(z, N):
    m = z.size
    if N % 2 == 0:
        return np.concatenate([z, z[::-1]])
    else:
        return np.concatenate([z, z[-2::-1]])


def construct(budget_seconds, start):
