        if not np.all(np.isfinite(h)):
            return False
        c = _C(h)
        if c < best_C:
            best_C = c
            best_h = h.copy()
            return True
        return False

    # Symmetric half-space chain
    def run_chain_sym(N, hseed, betas, maxiter):
