    F = (np.log(w.sum()) + m) / beta
    w = w / w.sum()
    g = np.correlate(w, h, 'valid')
    grad_h = 2.0 * g
    dot = np.dot(h, grad_h)
    grad = (2.0 * v / s) * (grad_h - dot)
    return F, grad


def _refine(v, beta, deadline, maxiter=400):
    if time.process_time() > deadline:
        return v
    try:
        res = minimize(lambda vv: _softmax_obj(vv, beta), v, jac=True,
                       method='L-BFGS-B',
                       options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13})
    except Exception:
        return v
    if res.x is not None and np.all(np.isfinite(res.x)):
        return res.x
    return v


def _resample(h, N):
    h = np.asarray(h, dtype=float).ravel()
    n = len(h)
    if n == N:
        return h.copy()
    xo = (np.arange(n) + 0.5) / n
    xn = (np.arange(N) + 0.5) / N
    return np.interp(xn, xo, h)


def _flatten_peak(h, bestC, deadline, iters=400):
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    if h.sum() <= 0:
        return h
    n = h.size
    for _ in range(iters):
        if time.process_time() > deadline:
            break
        c = np.convolve(h, h)
        peak = int(np.argmax(c))
        lo = max(0, peak - (n - 1))
        hi = min(n - 1, peak)
        idx = np.arange(lo, hi + 1)
        improved = False
        for step in (0.01, 0.003, 0.001, 0.0003, 0.0001):
            trial = h.copy()
            trial[idx] *= (1.0 - step)
            mass = (h[idx] * step).sum()
            outer = np.setdiff1d(np.arange(n), idx, assume_unique=True)
            if outer.size > 0 and mass > 0:
                trial[outer] += mass / outer.size
            if trial.sum() <= 0:
                continue
            tc = _C(trial)
            if tc < bestC - 1e-14:
                h = trial
                bestC = tc
                improved = True
                break
        if not improved:
            break
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        h0 = np.asarray(start, dtype=float).ravel()
        if h0.size == 0 or h0.sum() <= 0 or not np.all(np.isfinite(h0)):
            h0 = None
    else:
        h0 = None
    if h0 is None:
        x = np.linspace(-0.25, 0.25, 400)
        h0 = np.maximum(np.cos(2 * np.pi * x) ** 2, 1e-6)
    h0 = np.maximum(h0, 0.0)

    best_h = h0.copy()
    best_C = _C(h0)

    def consider(h):
        nonlocal best_h, best_C
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.size == 0 or h.size > 30000 or h.sum() <= 0:
            return False
        if not np.all(np.isfinite(h)):
            return False
        c = _C(h)
        if c < best_C - 1e-14:
            best_C = c
            best_h = h.copy()
            return True
        return False

    betas = np.geomspace(100.0, 5e7, 30)
    idx_hi = int(np.argmin(np.abs(np.log(betas) - np.log(1e5))))

    def run_ladder(N, hseed, beta_start_idx=0, maxiter=400, bl=None):
        if time.process_time() > deadline:
            return False
        bl = betas if bl is None else bl
        improved = False
        h = _resample(hseed, N)
        h = np.maximum(h, 1e-12)
        h = h / h.sum()
        if consider(h):
            improved = True
        v = np.sqrt(h)
        for i in range(beta_start_idx, len(bl)):
            if time.process_time() > deadline:
                break
            beta = bl[i]
            v = _refine(v, beta, deadline, maxiter=maxiter)
            v2 = v * v
            s = v2.sum()
            if s <= 0:
                continue
            if consider(v2 / s):
                improved = True
        return improved

    # Polish at the start's own resolution
    if start is not None:
        run_ladder(best_h.size, best_h, 0, 400)
        if time.process_time() < deadline:
            run_ladder(best_h.size, best_h, idx_hi, 400)

    # Try a couple of resolutions
    for N in (1200, 1600):
        if time.process_time() >= deadline:
            break
        run_ladder(N, best_h, 0, 400)

    # Flatten peak directly on best
    if time.process_time() < deadline:
        consider(_flatten_peak(best_h, best_C, deadline))

    no_improve = 0
    rng = np.random.default_rng(999)
    while time.process_time() < deadline:
        cycle = no_improve % 5
        N = best_h.size
        if cycle == 0:
            improved = run_ladder(N, best_h, idx_hi, 400)
        elif cycle == 1:
            local = np.geomspace(1e5, 1e8, 14)
            improved = run_ladder(N, best_h, 0, 400, bl=local)
        elif cycle == 2:
            h = best_h.copy()
            h = np.maximum(h * rng.lognormal(0.0, 0.003, size=h.size), 1e-12)
            h /= h.sum()
            improved = run_ladder(N, h, idx_hi, 400)
        elif cycle == 3:
            N2 = int(np.clip(N * 1.25, 200, 30000))
            improved = run_ladder(N2, best_h, 18, 400)
        else:
            improved = consider(_flatten_peak(best_h, best_C, deadline, iters=80))
        no_improve = 0 if improved else no_improve + 1

    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(200) / 200.0
    return best_h

