        h0 = np.maximum(np.cos(2 * np.pi * x) ** 2, 1e-6)
    h0 = np.maximum(h0, 0.0)

    best_h = h0.copy()
    best_C = _C(h0)

    def consider(h):
        nonlocal best_h, best_C
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        if h.size == 0 or h.size > 30000 or h.sum() <= 0:
            return False
        if not np.all(np.isfinite(h)):
            return False
        c = _C(h)
        if c < best_C - 1e-13:
            best_C = c
            best_h = h.copy()
            return True
        return False

    betas = np.geomspace(100.0, 5e7, 30)

    def run_ladder(N, hseed, beta_start_idx=0, maxiter=400, betas_local=None):
        if time.process_time() > deadline:
            return False
        bl = betas if betas_local is None else betas_local
        improved = False
        h = _resample(hseed, N)
        h = np.maximum(h, 1e-12)
        h = h / h.sum()
        if consider(h):
            improved = True
        v = np.sqrt(h)
        for i in range(beta_start_idx, len(bl)):
            if time.process_time() > deadline:
                break
            beta = bl[i]
            v = _refine(v, beta, deadline, maxiter=maxiter)
            v2 = v * v
            s = v2.sum()
            if s <= 0:
                continue
            hh = v2 / s
            if consider(hh):
                improved = True
        return improved

    if start is not None and best_h.size <= 30000:
        run_ladder(best_h.size, best_h, 0, 400)
        if time.process_time() < deadline and best_h.size <= 30000:
            run_ladder(best_h.size, best_h, 20, 400)

    for N in (1200, 1600, 2000):
        if time.process_time() >= deadline:
            break
        run_ladder(N, best_h, 0, 400)

    for N in (300, 600, 900):
        if time.process_time() >= deadline:
            break
        h = _resample(best_h, N)
        run_ladder(N, h, beta_start_idx=10, maxiter=400)
        polished = _lp_polish(best_h if best_h.size == N else _resample(best_h, N),
                              best_C, deadline)
