def _de_block_search(K, N, deadline, seed):
    """Global search over K block heights, expanded to N via np.repeat."""
    if time.process_time() > deadline:
        return None
    reps = N // K
    if reps < 1:
        return None
    Nuse = reps * K

    def obj(blocks):
        if np.any(blocks < 0):
            return 1e9
        h = np.repeat(blocks, reps)
        s = h.sum()
        if s <= 0:
            return 1e9
        c = np.convolve(h, h)
        return 2.0 * Nuse * np.max(c) / (s * s)

    try:
        res = differential_evolution(
            obj, [(0.0, 5.0)] * K, maxiter=80, popsize=15, tol=1e-8,
            seed=seed, polish=False, init='latinhypercube')
    except Exception:
        return None
    if res.x is None or not np.all(np.isfinite(res.x)):
        return None
    return np.maximum(res.x, 0.0)


