import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 2000
    x = -0.25 + (np.arange(N) + 0.5) / N

    def make(a):
        return np.exp(a * x)

    best_a = None
    best_C = np.inf
    best_h = None

    # coarse grid
    grid = np.linspace(0.5, 2.5, 200)
    for a in grid:
        if time.process_time() - t0 > budget_seconds * 0.5:
            break
        h = make(a)
        c = _C(h)
        if c < best_C:
            best_C = c
            best_a = a
            best_h = h

    # golden-section refine around best_a
    if best_a is not None:
        lo = max(0.5, best_a - 0.05)
        hi = min(2.5, best_a + 0.05)
        gr = (np.sqrt(5.0) - 1.0) / 2.0
        c_ = hi - gr * (hi - lo)
        d_ = lo + gr * (hi - lo)
        fc = _C(make(c_))
        fd = _C(make(d_))
        while hi - lo > 1e-4 and time.process_time() - t0 < budget_seconds * 0.85:
            if fc < fd:
                hi, d_, fd = d_, c_, fc
                c_ = hi - gr * (hi - lo)
                fc = _C(make(c_))
            else:
                lo, c_, fc = c_, d_, fd
                d_ = lo + gr * (hi - lo)
                fd = _C(make(d_))
        for a in (lo, hi, 0.5 * (lo + hi)):
            h = make(a)
            c = _C(h)
            if c < best_C:
                best_C = c
                best_a = a
                best_h = h

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    # Keep start if it happens to be better
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) < best_C:
            return s

    print("best a=%.5f C=%.6f" % (best_a, best_C))
    return best_h

