import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _build(a, b, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = a * x + b * x * x
    e -= e.max()
    return np.exp(e)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 2.0

    best_h = None
    best_C = 1e18

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0
            best_C = _C(h0)

    N_coarse = 1500
    # coarse grid
    a_vals = np.arange(0.0, 3.0001, 0.2)
    b_vals = np.arange(-10.0, 10.0001, 2.0)
    best_ab = (0.0, 0.0)
    for a in a_vals:
        for b in b_vals:
            if time.process_time() - t0 > deadline * 0.5:
                break
            h = _build(a, b, N_coarse)
            c = _C(h)
            if c < best_C:
                best_C = c
                best_ab = (a, b)
                best_h = h
        else:
            continue
        break

    # Nelder-Mead refine on coarse grid
    def obj(p):
        return _C(_build(p[0], p[1], N_coarse))

    try:
        if time.process_time() - t0 < deadline * 0.7:
            res = minimize(obj, np.array(best_ab), method='Nelder-Mead',
                           options={'xatol': 1e-4, 'fatol': 1e-7, 'maxiter': 400})
            if res.fun < best_C:
                best_C = res.fun
                best_ab = (res.x[0], res.x[1])
    except Exception:
        pass

    # rebuild at N=3000
    N_fine = 3000
    h_fine = _build(best_ab[0], best_ab[1], N_fine)
    c_fine = _C(h_fine)
    if c_fine < best_C:
        best_C = c_fine
        best_h = h_fine

    if best_h is None:
        best_h = np.ones(50)
    return np.asarray(best_h, dtype=float)

import numpy as np
import time


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    # Candidate N values: start from start's length, explore a grid
    if start is not None:
        base = np.asarray(start, dtype=float)
        best_h = base.copy()
        best_c = C_of(best_h)
        N0 = len(base)
    else:
        N0 = 50
        best_h = np.ones(N0)
        best_c = 2.0

    # The classic minimizer shape is close to a "triangle/parabola" bump.
    # For a step function on [-1/4,1/4] with autoconv max at center,
    # the continuous optimum is related to f(t) ~ sqrt(1-(2t)^2)-ish? Actually
    # the known optimum shape for this problem is f(t) = (1-4t^2) type.
    # We'll try parametric families and optimize scale-free shape.

    def candidate_tri(N):
        # triangular: peaks in middle, zero at edges
        x = np.linspace(-1, 1, N)
        return np.maximum(0.0, 1.0 - np.abs(x))

    def candidate_parab(N):
        x = np.linspace(-1, 1, N)
        return np.maximum(0.0, 1.0 - x * x)

    def candidate_sqrt(N):
        x = np.linspace(-1, 1, N)
        return np.sqrt(np.maximum(0.0, 1.0 - x * x))

    def candidate_cos(N):
        x = np.linspace(-1, 1, N)
        return np.maximum(0.0, np.cos(x * np.pi / 2))

    def candidate_const(N):
        return np.ones(N)

    families = [candidate_tri, candidate_parab, candidate_sqrt, candidate_cos, candidate_const]

    # Sweep N over a range and families
    Ns = sorted(set([N0, 2, 3, 4, 5, 6, 8, 10, 12, 15, 20, 25, 30, 40, 50, 64, 80, 100,
                     128, 160, 200, 256, 320, 400, 512, 640, 800, 1000, 1280, 1600,
                     2000, 2560, 3200, 4000, 5120, 6400, 8000, 10000, 12800, 16000, 20000]))

    for fam in families:
        for N in Ns:
            if time.process_time() > deadline:
                break
            h = fam(N)
            c = C_of(h)
            if c < best_c:
                best_c = c
                best_h = h.copy()

    # Local refinement: coordinate ascent on the best shape
    h = best_h.copy()
    c = best_c
    N = len(h)

    # Optimize via multiplicative / additive perturbations of blocks
    rng = np.random.default_rng(12345)

    # First: try to reduce N by downsampling (merge adjacent pairs) - often
    # fewer steps with same shape can have lower C due to discretization.
    def refine(h, c, deadline):
        N = len(h)
        improved = True
        step = max(1, N // 50)
        while improved and time.process_time() < deadline:
            improved = False
            # try additive tweaks to individual entries
            for i in range(N):
                if time.process_time() > deadline:
                    return h, c
                orig = h[i]
                # try a few multiplicative scalings
                for factor in (0.5, 0.8, 0.9, 1.1, 1.25, 2.0):
                    h[i] = orig * factor
                    nc = C_of(h)
                    if nc < c - 1e-12:
                        c = nc
                        orig = h[i]
                        improved = True
                    else:
                        h[i] = orig
                h[i] = orig
            if not improved:
                # try block smoothing
                for i in range(0, N - 1):
                    if time.process_time() > deadline:
                        return h, c
                    a, b = h[i], h[i + 1]
                    # try averaging
                    for w in (0.1, 0.25, 0.5):
                        h[i] = a * (1 - w) + b * w
                        h[i + 1] = b * (1 - w) + a * w
                        nc = C_of(h)
                        if nc < c - 1e-12:
                            c = nc
                            a, b = h[i], h[i + 1]
                            improved = True
                        else:
                            h[i], h[i + 1] = a, b
                    h[i], h[i + 1] = a, b
        return h, c

    # Try refining a few best candidates with different N
    # First, build small set of top candidates
    cands = []
    for fam in families:
        for N in Ns:
            if time.process_time() > deadline:
                break
            cands.append((C_of(fam(N)), fam(N)))
    cands.sort(key=lambda x: x[0])
    cands = cands[:8]

    for c0, h0 in cands:
        if time.process_time() > deadline:
            break
        hh, cc = refine(h0.copy(), c0, deadline)
        if cc < best_c:
            best_c = cc
            best_h = hh

    return best_h

