                           options={'xatol': 1e-5, 'fatol': 1e-8, 'maxiter': 600})
            if res.fun < best_C:
                best_C = res.fun
                best_ab = (res.x[0], res.x[1])
    except Exception:
        pass

    # Refine on fine N using Nelder-Mead directly (most accurate)
    for N_fine in Ns:
