import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5

    def elapsed():
        return time.process_time() - t0

    def cost(h):
        N = h.size
        s = h.sum()
        if s <= 0:
            return np.inf
        return 2.0 * N * np.convolve(h, h).max() / (s * s)

    # Candidate starting configurations
    candidates = []

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0 and s.size <= 30000:
            candidates.append(("start", s.copy(), cost(s)))

    # Smooth bump fallbacks
    for N in (3000, 6000, 12000):
        x = np.linspace(-1.0, 1.0, N)
        for a in (0.5, 0.7, 0.85, 1.0):
            for p in (1.0, 2.0, 3.0):
                m = np.abs(x) < a
                h = np.zeros(N)
                h[m] = np.cos(0.5 * np.pi * x[m] / a) ** p
                if h.sum() > 0:
                    candidates.append((f"bump{N}_{a}_{p}", h, cost(h)))

    candidates.sort(key=lambda r: r[2])
    best_name, h, best_c = candidates[0]
    h = np.asarray(h, dtype=float)
    h = h / h.sum()

    N = h.size

    # Incremental convolution helpers
    def make_conv(h):
        return np.convolve(h, h)

    conv = make_conv(h)

    # Try multiplicative change to a block, incrementally update conv
    def try_block(h, conv, i0, i1, factor):
        L = h.size
        seg = h[i0:i1]
        d = (factor - 1.0) * seg
        dh = np.convolve(d, h)
        new_conv = conv.copy()
        end = i0 + dh.size
        new_conv[i0:end] += 2.0 * dh
        dd = np.convolve(d, d)
        end2 = 2 * i0 + dd.size
        new_conv[2 * i0:end2] += dd
        new_h = h.copy()
        new_h[i0:i1] *= factor
        return new_h, new_conv

    def eval_c(h, conv):
        s = h.sum()
        if s <= 0:
            return np.inf
        return 2.0 * N * conv.max() / (s * s)

    rng = np.random.default_rng(987654321)

    # Multi-scale block coordinate ascent
    schedules = [
        (32, [0.3, 0.1, 0.03]),
        (16, [0.2, 0.06, 0.02]),
        (8,  [0.15, 0.05, 0.015]),
        (4,  [0.1, 0.03, 0.01]),
        (2,  [0.06, 0.02, 0.006]),
        (1,  [0.04, 0.012, 0.004]),
    ]

    for block, deltas in schedules:
        if elapsed() >= deadline:
            break
        nblocks = (N + block - 1) // block
        # several passes at this scale
        for _pass in range(3):
            if elapsed() >= deadline:
                break
            order = rng.permutation(nblocks)
            improved_any = False
            for bi in order:
                if elapsed() >= deadline:
                    break
                i0 = bi * block
                i1 = min(i0 + block, N)
                if i0 >= N:
                    continue
                seg = h[i0:i1]
                if seg.sum() <= 0:
                    continue
                for delta in deltas:
                    if elapsed() >= deadline:
                        break
                    hit = False
                    for factor in (np.exp(delta), np.exp(-delta)):
                        nh, nc = try_block(h, conv, i0, i1, factor)
                        c = eval_c(nh, nc)
                        if c < best_c - 1e-12:
                            h, conv, best_c = nh, nc, c
                            hit = True
                            improved_any = True
                            break
                    if hit:
                        break
            if not improved_any:
                break

    # Tail trimming: try zeroing outer steps
    if elapsed() < deadline:
        for _ in range(6):
            if elapsed() >= deadline:
                break
            nz = np.nonzero(h > 0)[0]
            if nz.size < 20:
                break
            improved = False
            for k in (1, 2, 3, 5, 8):
                if elapsed() >= deadline:
                    break
                if nz.size < 2 * k:
                    continue
                for idxs in (nz[:k], nz[-k:]):
                    trial = h.copy()
                    trial[idxs] = 0.0
                    if trial.sum() <= 0:
                        continue
                    tc = np.convolve(trial, trial)
                    c = 2.0 * N * tc.max() / (trial.sum() ** 2)
                    if c < best_c - 1e-12:
                        h, conv, best_c = trial, tc, c
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                break

    # Final single-coordinate polish with tiny steps
    if elapsed() < deadline:
        step = 0.01
        while elapsed() < deadline and step > 1e-5:
            improved = False
            idxs = rng.permutation(N)
            for i in idxs:
                if elapsed() >= deadline:
                    break
                base = h[i]
                for fac in (1 + step, 1 - step):
                    tv = base * fac
                    if tv < 0:
                        continue
                    H = h.copy()
                    H[i] = tv
                    cn = cost(H)
                    if cn < best_c - 1e-13:
                        h = H
                        best_c = cn
                        improved = True
                        break
                if improved and step > 1e-3:
                    # don't scan all coords at every improvement
                    pass
            if not improved:
                step *= 0.5

    h = np.asarray(h, dtype=float)
    h[h < 0] = 0
    if h.sum() <= 0:
        return np.ones(50)
    return h

import numpy as np
