def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _softmax_beta(x, beta):
    z = beta * (x - x.max())
    e = np.exp(z)
    return e / e.sum()


def _resize(h, N):
    h = np.asarray(h, dtype=float)
    if h.size == N:
        return h.copy()
    x_old = (np.arange(h.size) + 0.5) / h.size
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _irls(h, N, betas, steps, t0, deadline):
    """Exponentiated-gradient descent on soft-max of autoconvolution."""
    h = h.copy()
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    for beta in betas:
        eta = 0.5 / beta
        for _ in range(steps):
            if time.process_time() - t0 > deadline:
                return h
            conv = np.convolve(h, h)
            w = _softmax_beta(conv, beta)
            # gradient of sum_i w_i (h*h)_i wrt h: 2 * (w conv h) (with symmetric w)
            g = 2.0 * np.convolve(w, h, mode='same')
            h = h * np.exp(-eta * g)
            s = h.sum()
            if s <= 0 or not np.isfinite(s):
                return h
            h /= s
    return h


def _polish(h, N, t0, deadline, iters=400):
    """Coordinate-wise multiplicative polish on exact C at resolution N."""
    h = _resize(h, N)
    s = h.sum()
    if s <= 0:
        return h
    h /= s
    best = h.copy()
    bestC = _C(h)
    rng = np.random.default_rng(12345)
    step = 0.08
    for it in range(iters):
        if time.process_time() - t0 > deadline:
            break
        improved = False
        # try a few random coordinate perturbations
        idxs = rng.integers(0, N, size=8)
        for i in idxs:
            for mult in (1.0 + step, 1.0 / (1.0 + step)):
                h2 = h.copy()
                h2[i] *= mult
                c2 = _C(h2)
                if c2 < bestC:
                    bestC = c2
                    h = h2 / h2.sum()
                    best = h.copy()
                    improved = True
                    break
        if not improved:
            step *= 0.7
            if step < 1e-4:
                break
    return best


