    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _build(p, N):
    # p = [a1,a2,a3,a4, b1,b2,b3,b4]
    x = -0.25 + (np.arange(N) + 0.5) / N
    a = p[0:4]
    b = p[4:8]
    xl = np.where(x < 0, x, 0.0)
    xr = np.where(x >= 0, x, 0.0)
    eL = a[0]*xl + a[1]*xl**2 + a[2]*xl**3 + a[3]*xl**4
    eR = b[0]*xr + b[1]*xr**2 + b[2]*xr**3 + b[3]*xr**4
    e = np.where(x < 0, eL, eR)
    e -= e.max()
    return np.exp(e)


def _c_of(p, N):
    return _C(_build(p, N))


def _fit_half(x, y, deg=4):
    # fit y ~ c1 x + c2 x^2 + ... + cdeg x^deg (no constant)
    A = np.stack([x**k for k in range(1, deg+1)], axis=1)
    try:
        coef, *_ = np.linalg.lstsq(A, y, rcond=None)
        return coef
    except Exception:
        return np.zeros(deg)


