import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _build(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = p[0]*x + p[1]*x*x + p[2]*x**3 + p[3]*x**4 + p[4]*x**5
    e -= e.max()
    return np.exp(e)


def _c_of(p, N):
    return _C(_build(p, N))


def _fit_p(h):
    """Fit log(h) ~ poly degree 5 on [-.25,.25], return 5 params [x..x^5]."""
    N = len(h)
    x = -0.25 + (np.arange(N) + 0.5) / N
    mask = h > h.max() * 1e-8
    if mask.sum() < 6:
        return None
    try:
        coef = np.polyfit(x[mask], np.log(h[mask]), 5)  # x^5..x^0
        p = np.array([coef[5-k] for k in range(1, 6)])
        return p
    except Exception:
        return None


def _block_polish(h, deadline, t0, rng):
    """Block coordinate ascent on exact C with multiplicative line search."""
    h = h.copy()
    N = len(h)
    best_C = _C(h)
    block = 20
    # step sizes schedule
    steps = [0.2, 0.1, 0.05, 0.025, 0.012, 0.006, 0.003]
    nblocks = (N + block - 1) // block
    for s in steps:
        if time.process_time() - t0 > deadline:
            break
        improved_any = False
        order = rng.permutation(nblocks)
        for bi in order:
            if time.process_time() - t0 > deadline:
                break
            lo = bi * block
            hi = min(lo + block, N)
            if hi <= lo:
                continue
            base = h[lo:hi].copy()
            # try a few random directions plus a uniform one
            dirs = [np.ones(hi - lo)]
            for _ in range(3):
                dirs.append(rng.standard_normal(hi - lo))
            for d in dirs:
                d = d - d.mean()
                for sign in (1.0, -1.0):
                    if time.process_time() - t0 > deadline:
                        break
                    h[lo:hi] = base * np.exp(sign * s * d)
                    c = _C(h)
                    if c < best_C - 1e-12:
                        best_C = c
                        base = h[lo:hi].copy()
                        improved_any = True
                    else:
                        h[lo:hi] = base
        if not improved_any:
            continue
    return h, best_C


