def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    n = len(h)
    m = 1
    while m < 2 * n:
        m *= 2
    H = np.fft.rfft(h, m)
    conv = np.fft.irfft(H * H, m)
    return 2.0 * n * np.max(conv[:2 * n - 1]) / (s * s)


def _build(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = np.zeros(N)
    xp = np.ones(N)
    for k in range(1, len(p) + 1):
        xp = xp * x
        e += p[k - 1] * xp
    e -= e.max()
    return np.exp(e)


def _c_of(p, N):
    return _C(_build(p, N))


