import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_conv(h):
    s = h.sum()
    c = np.convolve(h, h)
    return 2.0 * len(h) * c.max() / (s * s), c


def _build(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = p[0]*x + p[1]*x*x + p[2]*x**3 + p[3]*x**4 + p[4]*x**5
    e -= e.max()
    return np.exp(e)


def _fit_p(h):
    N = len(h)
    x = -0.25 + (np.arange(N) + 0.5) / N
    mask = h > h.max() * 1e-8
    if mask.sum() < 6:
        return None
    try:
        coef = np.polyfit(x[mask], np.log(h[mask]), 5)
        return np.array([coef[5-k] for k in range(1, 6)])
    except Exception:
        return None


def _grad_C(h):
    """Gradient of C w.r.t. h at current point (numerically via autoconv).
    C = 2N * M / S^2, M = max conv, S = sum h.
    dC/dh_i = 2N/S^2 * dM/dh_i - 2*C/S * 1
    dM/dh_i: at argmax j, conv[j] = sum_k h_k h_{j-k}, so dM/dh_i = 2*h[j-i] (with valid index)
    """
    N = len(h)
    S = h.sum()
    conv = np.convolve(h, h)
    j = int(np.argmax(conv))
    M = conv[j]
    C = 2.0 * N * M / (S * S)
    # dM/dh_i = 2 * h[j-i] for i in [max(0,j-(N-1)), min(N-1,j)]
    g = np.zeros(N)
    lo = max(0, j - (N - 1))
    hi = min(N - 1, j)
    idx = np.arange(lo, hi + 1)
    g[idx] = 2.0 * h[j - idx]
    dC = (2.0 * N / (S * S)) * g - (2.0 * C / S)
    return C, dC


def _block_polish_multipass(h, deadline, t0, rng):
    """Block coordinate ascent with multiplicative updates; multiple block sizes."""
    h = h.copy()
    N = len(h)
    best_C = _C(h)
    for block in [40, 20, 10, 5, 2]:
        if time.process_time() - t0 > deadline:
            break
        nblocks = (N + block - 1) // block
        steps = [0.15, 0.07, 0.035, 0.017, 0.008, 0.004, 0.002]
        for s in steps:
            if time.process_time() - t0 > deadline:
                break
            improved_any = False
            order = rng.permutation(nblocks)
            for bi in order:
                if time.process_time() - t0 > deadline:
                    break
                lo = bi * block
                hi = min(lo + block, N)
                if hi <= lo:
                    continue
                base = h[lo:hi].copy()
                dirs = [np.ones(hi - lo)]
                for _ in range(2):
                    dirs.append(rng.standard_normal(hi - lo))
                for d in dirs:
                    d = d - d.mean()
                    for sign in (1.0, -1.0):
                        h[lo:hi] = base * np.exp(sign * s * d)
                        c = _C(h)
                        if c < best_C - 1e-13:
                            best_C = c
                            base = h[lo:hi].copy()
                            improved_any = True
                        else:
                            h[lo:hi] = base
            if not improved_any and s <= 0.008:
                break
    return h, best_C


def _grad_descent(h, deadline, t0, n_steps=200):
    """Projected gradient descent on C with multiplicative step (stays positive)."""
    h = h.copy()
    N = len(h)
    C, _ = _C_and_conv(h)
    lr = 1e-3
    for it in range(n_steps):
        if time.process_time() - t0 > deadline:
            break
        C, g = _grad_C(h)
        # normalize gradient and take multiplicative step
        gn = np.linalg.norm(g)
        if gn < 1e-15:
            break
        # step in -g direction, multiplicative
        step = lr * g / (gn + 1e-15)
        step = step - step.mean()
        newh = h * np.exp(-step)
        newC = _C(newh)
        if newC < C - 1e-13:
            h = newh
            lr *= 1.05
        else:
            lr *= 0.5
            if lr < 1e-7:
                break
    return h, _C(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5
    rng = np.random.default_rng(20240129)

    best_h = None
    best_C = 1e18

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    # Resize start to a nicer working N if it's small, but keep original as candidate
    if best_h is not None and len(best_h) < 8000 and len(best_h) >= 8:
        # upsample to 3000 via poly fit
        p0 = _fit_p(best_h)
        if p0 is not None:
            h_up = _build(p0, 3000)
            cu = _C(h_up)
            if cu < best_C:
                best_h = h_up
                best_C = cu

    # Phase A: gradient descent polish
    if best_h is not None:
        h_gd, c_gd = _grad_descent(best_h, deadline * 0.35, t0, n_steps=300)
        if c_gd < best_C:
            best_C = c_gd
            best_h = h_gd

    # Phase B: block polish
    if best_h is not None:
        h_pol, c_pol = _block_polish_multipass(best_h, deadline * 0.75, t0, rng)
        if c_pol < best_C:
            best_C = c_pol
            best_h = h_pol

    # Phase C: smooth re-optimization on 3000 grid, then block again
    p_seed = _fit_p(best_h) if best_h is not None else None
    if p_seed is not None and time.process_time() - t0 < deadline * 0.85:
        N_fine = 3000

        def obj(p):
            return _C(_build(p, N_fine))

        try:
            res = minimize(obj, p_seed, method='Nelder-Mead',
                           options={'xatol': 1e-7, 'fatol': 1e-11, 'maxiter': 800})
            h_new = _build(res.x, N_fine)
            c_new = _C(h_new)
            if c_new < best_C:
                best_C = c_new
                best_h = h_new
        except Exception:
            pass

    # Phase D: final block polish
    if best_h is not None and time.process_time() - t0 < deadline:
        h_pol, c_pol = _block_polish_multipass(best_h, deadline, t0, rng)
        if c_pol < best_C:
            best_C = c_pol
            best_h = h_pol

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) < best_C:
            return s

    print("C=%.9f N=%d" % (best_C, len(best_h)))
    return np.asarray(best_h, dtype=float)

