import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _build(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = p[0]*x + p[1]*x*x + p[2]*x**3 + p[3]*x**4 + p[4]*x**5
    e -= e.max()
    return np.exp(e)


def _c_of(p, N):
    return _C(_build(p, N))


def _recover_p(h0):
    N0 = len(h0)
    x0 = -0.25 + (np.arange(N0) + 0.5) / N0
    mask = h0 > h0.max() * 1e-6
    if mask.sum() < 5:
        return None
    try:
        coef = np.polyfit(x0[mask], np.log(h0[mask]), 5)
        p = np.zeros(5)
        for k in range(1, 6):
            p[k-1] = coef[5 - k]
        return p
    except Exception:
        return None


def _newton_polish(p0, N, max_iter=60):
    """Newton/Gauss-Newton style polish on the active max-knot."""
    p = p0.copy()
    h = _build(p, N)
    best_C = _C(h)
    best_p = p.copy()
    eps = 1e-5
    for _ in range(max_iter):
        # gradient via finite differences
        g = np.zeros(5)
        for k in range(5):
            pp = p.copy(); pp[k] += eps
            pm = p.copy(); pm[k] -= eps
            g[k] = (_c_of(pp, N) - _c_of(pm, N)) / (2*eps)
        # approximate Hessian via diagonal + local line search
        improved = False
        step = 1e-3
        for _ls in range(30):
            pn = p - step * g / (np.linalg.norm(g) + 1e-12)
            cn = _c_of(pn, N)
            if cn < best_C - 1e-12:
                p = pn
                best_C = cn
                best_p = p.copy()
                improved = True
                step *= 1.6
            else:
                step *= 0.5
        if not improved:
            break
    return best_p, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5

    best_h = None
    best_C = 1e18
    best_p = None

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    seed_p = None
    if start is not None and len(start) >= 8:
        seed_p = _recover_p(np.asarray(start, dtype=float))

    N_coarse = 1500

    seeds = []
    if seed_p is not None:
        seeds.append(seed_p.copy())
        rng = np.random.RandomState(12345)
        for _ in range(4):
            seeds.append(seed_p + rng.randn(5) * 0.1)
    seeds += [
        np.array([1.26, 0.0, 0.0, 0.0, 0.0]),
        np.array([1.0, 2.0, 0.0, 0.0, 0.0]),
        np.array([1.5, -2.0, 0.0, 0.0, 0.0]),
        np.array([1.0, 0.0, 5.0, 0.0, 0.0]),
        np.array([0.5, 3.0, 0.0, -5.0, 0.0]),
        np.array([2.0, 0.0, 0.0, -8.0, 0.0]),
        np.array([1.3, 0.0, 0.0, 0.0, 4.0]),
    ]

    def obj(p):
        return _c_of(p, N_coarse)

    best_local = None
    for seed in seeds:
        if time.process_time() - t0 > deadline * 0.40:
            break
        try:
            res = minimize(obj, seed, method='Nelder-Mead',
                           options={'xatol': 1e-6, 'fatol': 1e-11, 'maxiter': 900})
            if best_local is None or res.fun < best_local.fun:
                best_local = res
        except Exception:
            pass

    if best_local is not None:
        best_p = best_local.x
        h_c = _build(best_p, N_coarse)
        c_c = _C(h_c)
        if c_c < best_C:
            best_C = c_c
            best_h = h_c

    # Refine on full grid with Nelder-Mead
    N_fine = 3000
    if best_p is not None and time.process_time() - t0 < deadline * 0.72:
        def obj_fine(p):
            return _c_of(p, N_fine)
        try:
            res = minimize(obj_fine, best_p, method='Nelder-Mead',
                           options={'xatol': 1e-8, 'fatol': 1e-13, 'maxiter': 1500})
            if res.fun < best_C:
                best_p = res.x
                best_h = _build(best_p, N_fine)
                best_C = res.fun
        except Exception:
            pass

    # Powell polish
    if best_p is not None and time.process_time() - t0 < deadline * 0.88:
        try:
            res = minimize(lambda p: _c_of(p, N_fine), best_p, method='Powell',
                           options={'xtol': 1e-9, 'ftol': 1e-13, 'maxiter': 600})
            if res.fun < best_C:
                best_p = res.x
                best_h = _build(best_p, N_fine)
                best_C = res.fun
        except Exception:
            pass

    # Newton-style polish for final squeeze
    if best_p is not None and time.process_time() - t0 < deadline * 0.96:
        try:
            pn, cn = _newton_polish(best_p, N_fine)
            if cn < best_C:
                best_p = pn
                best_h = _build(best_p, N_fine)
                best_C = cn
        except Exception:
            pass

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) < best_C:
            return s

    print("C=%.6f p=%s" % (best_C, np.round(best_p, 4) if best_p is not None else None))
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _build_spline(c, N, K=14):
    # c: K control values on equally spaced x in [-0.25, 0.25]
    x = -0.25 + (np.arange(N) + 0.5) / N
    xc = np.linspace(-0.25, 0.25, K)
    e = np.interp(x, xc, c)
    e -= e.max()
    return np.exp(e)


def _c_of_spline(c, N, K=14):
    return _C(_build_spline(c, N, K))


def _seed_from_h(h0, K=14):
    N0 = len(h0)
    x0 = -0.25 + (np.arange(N0) + 0.5) / N0
    xc = np.linspace(-0.25, 0.25, K)
    lh = np.log(np.maximum(h0, h0.max() * 1e-12))
    c = np.interp(xc, x0, lh)
    c = c - c[0]
    return c


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5
    K = 14

    best_h = None
    best_C = 1e18
    best_c = None

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    # Seed controls from start
    if start is not None and len(start) >= 4:
        c_seed = _seed_from_h(np.asarray(start, dtype=float), K)
    else:
        xc = np.linspace(-0.25, 0.25, K)
        c_seed = -((xc * 2) ** 2) * 4.0
        c_seed = c_seed - c_seed[0]

    # free params: c[1:] (c[0] fixed to 0)
    def unpack(q):
        c = np.empty(K)
        c[0] = 0.0
        c[1:] = q
        return c

    N_coarse = 1500

    def obj(q):
        return _c_of_spline(unpack(q), N_coarse, K)

    q0 = c_seed[1:].copy()

    best_q = q0.copy()
    best_local_fun = obj(q0)

    # Try a few perturbed seeds too
    seeds = [q0.copy()]
    rng = np.random.RandomState(12345)
    for _ in range(2):
        seeds.append(q0 + rng.normal(0, 0.3, size=K - 1))

    for seed in seeds:
        if time.process_time() - t0 > deadline * 0.5:
            break
        try:
            res = minimize(obj, seed, method='Nelder-Mead',
                           options={'xatol': 1e-5, 'fatol': 1e-9,
                                    'maxiter': 2000, 'maxfev': 2000 * (K + 2)})
            if res.fun < best_local_fun:
                best_local_fun = res.fun
                best_q = res.x.copy()
        except Exception:
            pass

    best_c = unpack(best_q)

    # Polish at N=6000
    if time.process_time() - t0 < deadline * 0.85:
        N_fine = 6000

        def obj_fine(q):
            return _c_of_spline(unpack(q), N_fine, K)

        try:
            res = minimize(obj_fine, best_q, method='Nelder-Mead',
                           options={'xatol': 1e-6, 'fatol': 1e-10,
                                    'maxiter': 1500, 'maxfev': 1500 * (K + 2)})
            if res.fun < best_local_fun:
                best_q = res.x.copy()
                best_local_fun = res.fun
        except Exception:
            pass
        best_c = unpack(best_q)

    # Build final at N=6000
    h_new = _build_spline(best_c, 6000, K)
    c_new = _C(h_new)

    if c_new < best_C:
        best_h = h_new
        best_C = c_new

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) <= best_C:
            print("C=%.6f (kept start)" % _C(s))
            return s

    print("C=%.6f spline K=%d" % (best_C, K))
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _convolve_peak(h):
    # np.convolve is fine but we only need the max
    return np.max(np.convolve(h, h))


def _C_fast(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * _convolve_peak(h) / (s * s)


def _build(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = np.zeros(N)
    xp = np.ones(N)
    for k in range(len(p)):
        xp = xp * x
        e += p[k] * xp
    e -= e.max()
    return np.exp(e)


def _c_of(p, N):
    return _C_fast(_build(p, N))


def _fit_poly(h0, deg):
    N0 = len(h0)
    x0 = -0.25 + (np.arange(N0) + 0.5) / N0
    mask = h0 > h0.max() * 1e-6
    if mask.sum() < deg + 2:
        return None
    try:
        coef = np.polyfit(x0[mask], np.log(h0[mask]), deg)
    except Exception:
        return None
    p = np.zeros(deg)
    for k in range(1, deg + 1):
        p[k - 1] = coef[deg - k]
    return p


def _grad_C_exact(h, eps=1e-6):
    """Finite-difference gradient of C w.r.t. h (log-parametrised)."""
    N = len(h)
    C0 = _C_fast(h)
    g = np.zeros(N)
    for i in range(N):
        h2 = h.copy()
        h2[i] *= (1.0 + eps)
        g[i] = (_C_fast(h2) - C0) / eps
    return g


def _block_polish(h, deadline, t0, rng, block=40):
    """Block coordinate ascent with multiplicative line search."""
    h = h.copy()
    N = len(h)
    best_C = _C_fast(h)
    steps = [0.15, 0.08, 0.04, 0.02, 0.01, 0.005, 0.0025, 0.0012]
    nblocks = (N + block - 1) // block
    for s in steps:
        if time.process_time() - t0 > deadline:
            break
        improved_any = False
        order = rng.permutation(nblocks)
        for bi in order:
            if time.process_time() - t0 > deadline:
                break
            lo = bi * block
            hi = min(lo + block, N)
            if hi <= lo:
                continue
            base = h[lo:hi].copy()
            dirs = [np.ones(hi - lo)]
            for _ in range(2):
                dirs.append(rng.standard_normal(hi - lo))
            for d in dirs:
                d = d - d.mean()
                for sign in (1.0, -1.0):
                    if time.process_time() - t0 > deadline:
                        break
                    h[lo:hi] = base * np.exp(sign * s * d)
                    c = _C_fast(h)
                    if c < best_C - 1e-13:
                        best_C = c
                        base = h[lo:hi].copy()
                        improved_any = True
                    else:
                        h[lo:hi] = base
        if not improved_any:
            # try to escape: perturb whole array slightly
            continue
    return h, best_C


def _refine_with_LBFGS(h, deadline, t0):
    """Direct L-BFGS on log-h with numerical gradient — expensive but precise."""
    N = len(h)
    # work on a coarse parametrisation: use every block representative
    # Actually do L-BFGS via scipy on the full array with analytic-ish FD
    def f(logh):
        hh = np.exp(logh - logh.max())
        return _C_fast(hh)

    logh0 = np.log(np.maximum(h, 1e-12))
    logh0 -= logh0.max()
    try:
        res = minimize(f, logh0, method='L-BFGS-B',
                       options={'maxiter': 200, 'eps': 1e-6, 'ftol': 1e-12, 'gtol': 1e-10},
                       callback=lambda xk: time.process_time() - t0 > deadline)
    except Exception:
        return h, _C_fast(h)
    if res.fun < _C_fast(h):
        hh = np.exp(res.x - res.x.max())
        return hh, res.fun
    return h, _C_fast(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5
    rng = np.random.default_rng(98765)

    best_h = None
    best_C = 1e18
    best_p = None

    if start is not None:
        h0 = np.asarray(start, dtype=float)
