import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_fast(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _upsample(h, N):
    """Linear interpolation of heights onto N equal steps over [-1/4,1/4]."""
    M = len(h)
    if M == N:
        return h.copy()
    x_old = -0.25 + (np.arange(M) + 0.5) / M
    x_new = -0.25 + (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _grad_C(h):
    """Analytic gradient of C(h) = 2N * max(conv(h,h)) / (sum h)^2.

    dC/dh_i = 2N * [ (dM/dh_i) * S^2 - M * 2 S ] / S^4
            = 2N/S^2 * dM/dh_i - 2*C/S * 1
    where M = max(conv), and dM/dh_i = 2 * (h * delta) ... actually
    conv(h,h)[k] = sum_j h_j h_{k-j}; d/dh_i conv[k] = h_{k-i} + h_{i-k}
    (with valid indices). Only the argmax k* matters.
    """
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.zeros(N)
    conv = np.convolve(h, h)
    k = int(np.argmax(conv))
    M = conv[k]
    C = 2.0 * N * M / (S * S)
    # dM/dh_i: contributions where i + j = k or j + i = k, i.e. h_{k-i} appears twice
    # conv[k] = sum_j h_j h_{k-j}. d/dh_i = h_{k-i} (if 0<=k-i<N) + h_{k-i} (if 0<=k-i<N, from j=k-i)
    # Actually both terms are h_{k-i} when 0<=k-i<N, giving 2*h_{k-i}.
    gM = np.zeros(N)
    idx = k - np.arange(N)
    mask = (idx >= 0) & (idx < N)
    gM[mask] = 2.0 * h[idx[mask]]
    g = (2.0 * N / (S * S)) * gM - (2.0 * C / S)
    return g


def _refine_lbfgs(h, deadline, t0, maxiter=300):
    """L-BFGS-B on log-h with analytic gradient."""
    N = len(h)
    logh0 = np.log(np.maximum(h, 1e-12))
    logh0 -= logh0.max()

    def f(logh):
        hh = np.exp(logh - logh.max())
        return _C_fast(hh)

    def g(logh):
        # chain rule: h = exp(logh - max), but max shift is constant w.r.t. shape;
        # we treat logh directly (shift invariance means gradient along 1 is ~0)
        hh = np.exp(logh - logh.max())
        gh = _grad_C(hh)
        # d h_j / d logh_i = h_j * (delta_ij - delta_{i,argmax})
        # approximate: ignore max-shift coupling (small effect)
        gl = gh * hh
        gl -= gl.mean()
        return gl

    try:
        res = minimize(f, logh0, jac=g, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'ftol': 1e-14, 'gtol': 1e-12},
                       callback=lambda xk: time.process_time() - t0 > deadline)
        hh = np.exp(res.x - res.x.max())
        c = _C_fast(hh)
        if c < _C_fast(h):
            return hh, c
    except Exception:
        pass
    return h, _C_fast(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5
    rng = np.random.default_rng(98765)

    best_h = None
    best_C = 1e18

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C_fast(h0)

    if best_h is None:
        best_h = np.ones(50)
        best_C = _C_fast(best_h)

    # Stage 1: upsample to N=12000 and refine with analytic-gradient L-BFGS-B
    if time.process_time() - t0 < deadline * 0.55:
        h12 = _upsample(best_h, 12000)
        h12, c12 = _refine_lbfgs(h12, deadline * 0.55, t0, maxiter=400)
        if c12 < best_C - 1e-13:
            best_C = c12
            best_h = h12
            print("N=12000 C=%.6f" % best_C)

    # Stage 2: upsample to N=24000 and refine
    if time.process_time() - t0 < deadline * 0.95:
        h24 = _upsample(best_h, 24000)
        h24, c24 = _refine_lbfgs(h24, deadline * 0.95, t0, maxiter=400)
        if c24 < best_C - 1e-13:
            best_C = c24
            best_h = h24
            print("N=24000 C=%.6f" % best_C)

    # Final safety: compare against original start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C_fast(s) < best_C:
            return s

    print("C=%.6f N=%d" % (best_C, len(best_h)))
    return np.asarray(best_h, dtype=float)

