    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (S * S)
    # dC/dh[j] = 2N/S^2 * dM/dh[j] - 4N*M/S^3
    # dM/dh[j] = 2*h[m-j] for valid indices
    g = np.full(N, -4.0 * N * M / (S ** 3))
    # valid j: 0 <= m-j <= N-1  =>  m-N+1 <= j <= m
    lo = max(0, m - N + 1)
    hi = min(N - 1, m)
    if hi >= lo:
        idx = np.arange(lo, hi + 1)
        g[idx] += (2.0 * N / (S * S)) * 2.0 * h[m - idx]
    return C, g


def _block_polish(h, deadline, t0, rng, block=40):
    h = h.copy()
    N = len(h)
    best_C = _C_fast(h)
    steps = [0.15, 0.08, 0.04, 0.02, 0.01, 0.005, 0.0025, 0.0012]
    nblocks = (N + block - 1) // block
    for s in steps:
        if time.process_time() - t0 > deadline:
            break
        improved_any = False
        order = rng.permutation(nblocks)
        for bi in order:
            if time.process_time() - t0 > deadline:
                break
            lo = bi * block
            hi = min(lo + block, N)
            if hi <= lo:
                continue
            base = h[lo:hi].copy()
            dirs = [np.ones(hi - lo)]
            for _ in range(2):
                dirs.append(rng.standard_normal(hi - lo))
            for d in dirs:
                d = d - d.mean()
                for sign in (1.0, -1.0):
                    if time.process_time() - t0 > deadline:
                        break
                    h[lo:hi] = base * np.exp(sign * s * d)
                    c = _C_fast(h)
                    if c < best_C - 1e-13:
                        best_C = c
                        base = h[lo:hi].copy()
                        improved_any = True
                    else:
                        h[lo:hi] = base
        if not improved_any:
            continue
    return h, best_C


def _refine_with_LBFGS(h, deadline, t0):
    N = len(h)

    def f(logh):
        hh = np.exp(logh - logh.max())
        return _C_fast(hh)

    logh0 = np.log(np.maximum(h, 1e-12))
    logh0 -= logh0.max()
    try:
        res = minimize(f, logh0, method='L-BFGS-B',
                       options={'maxiter': 200, 'eps': 1e-6, 'ftol': 1e-12, 'gtol': 1e-10},
                       callback=lambda xk: time.process_time() - t0 > deadline)
    except Exception:
        return h, _C_fast(h)
    if res.fun < _C_fast(h):
        hh = np.exp(res.x - res.x.max())
        return hh, res.fun
    return h, _C_fast(h)


def _analytic_lbfgs(h, deadline, t0, maxiter=300):
    """L-BFGS-B on log h with analytic gradient of C."""
    N = len(h)
    logh0 = np.log(np.maximum(h, 1e-12))
    logh0 -= logh0.max()

    def fg(logh):
        hh = np.exp(logh - logh.max())
        C, g = _C_and_grad(hh)
        # dC/dlogh[j] = h[j] * dC/dh[j]  (chain rule; the max-shift cancels)
        glog = hh * g
        return C, glog

    try:
        res = minimize(fg, logh0, method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-12,
                                'maxcor': 20},
                       callback=lambda xk: time.process_time() - t0 > deadline)
    except Exception:
        return h, _C_fast(h)
    hh = np.exp(res.x - res.x.max())
    c = _C_fast(hh)
    if c < _C_fast(h):
        return hh, c
    return h, _C_fast(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5
    rng = np.random.default_rng(98765)

    best_h = None
    best_C = 1e18
    best_p = None

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C_fast(h0)

    # Primary path: analytic-gradient L-BFGS on the start array.
    if best_h is not None:
        # First pass: analytic L-BFGS on log h
        if time.process_time() - t0 < deadline * 0.55:
            h_a, c_a = _analytic_lbfgs(best_h, deadline * 0.55, t0, maxiter=400)
            if c_a < best_C:
                best_C = c_a
                best_h = h_a
        # Second pass: another round from refined point
        if time.process_time() - t0 < deadline * 0.80:
            h_a, c_a = _analytic_lbfgs(best_h, deadline * 0.80, t0, maxiter=400)
            if c_a < best_C:
                best_C = c_a
                best_h = h_a

    # Recover seed polynomial from start (fallback / extra seeds)
    seed9 = np.zeros(9)
    if start is not None and len(start) >= 8:
        p9 = _fit_poly(np.asarray(start, dtype=float), 9)
        if p9 is not None:
            seed9 = p9

    # Only run the expensive polynomial search if analytic path stalled early
    if time.process_time() - t0 < deadline * 0.85:
        N_coarse = 1500
        seeds = [seed9.copy()]
        base_seeds = [
            np.array([1.26, 0.0, 0.0, 0.0, 0.0]),
            np.array([1.0, 2.0, 0.0, 0.0, 0.0]),
        ]
        for s in base_seeds:
            p9 = np.zeros(9)
            p9[:5] = s
            seeds.append(p9)

        def obj(p):
            return _c_of(p, N_coarse)

        best_local = None
        for seed in seeds:
            if time.process_time() - t0 > deadline * 0.90:
                break
            try:
                res = minimize(obj, seed, method='Nelder-Mead',
                               options={'xatol': 1e-5, 'fatol': 1e-9, 'maxiter': 800})
                if best_local is None or res.fun < best_local.fun:
                    best_local = res
            except Exception:
                pass
        if best_local is not None:
            h_c = _build(best_local.x, N_coarse)
            c_c = _C_fast(h_c)
            if c_c < best_C:
                # refine this candidate with analytic L-BFGS
                h_c2, c_c2 = _analytic_lbfgs(h_c, deadline * 0.95, t0, maxiter=200)
                if c_c2 < best_C:
                    best_C = c_c2
                    best_h = h_c2
                    best_p = best_local.x

    # Final block polish on best array
    if best_h is not None and time.process_time() - t0 < deadline * 0.97:
        h_pol, c_pol = _block_polish(best_h, deadline * 0.99, t0, rng)
        if c_pol < best_C:
            best_C = c_pol
            best_h = h_pol

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C_fast(s) < best_C:
            return s

    print("C=%.9f N=%d" % (best_C, len(best_h)))
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _build_poly(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = np.zeros(N)
    xp = np.ones(N)
    for k in range(len(p)):
        xp = xp * x
        e += p[k] * xp
    e -= e.max()
    return np.exp(e)


def _fit_poly(h0, deg):
    N0 = len(h0)
    x0 = -0.25 + (np.arange(N0) + 0.5) / N0
    mask = h0 > h0.max() * 1e-8
    if mask.sum() < deg + 2:
        return None
    try:
        coef = np.polyfit(x0[mask], np.log(h0[mask]), deg)
    except Exception:
        return None
    p = np.zeros(deg)
    for k in range(1, deg + 1):
        p[k - 1] = coef[deg - k]
    return p


def _smooth(h, w=2):
    # light smoothing
    if w <= 0:
        return h
    k = np.ones(2 * w + 1)
    k /= k.sum()
    s = np.convolve(h, k, mode='same')
    # fix edges
    return np.maximum(s, 1e-12)


def _block_polish(h, deadline, t0, rng, block=30):
    h = h.copy()
    N = len(h)
    best_C = _C(h)
    steps = [0.06, 0.03, 0.015, 0.008, 0.004, 0.002]
    nblocks = (N + block - 1) // block
    for s in steps:
        if time.process_time() - t0 > deadline:
            break
        for bi in rng.permutation(nblocks):
            if time.process_time() - t0 > deadline:
                break
            lo = bi * block
            hi = min(lo + block, N)
            base = h[lo:hi].copy()
            for _ in range(2):
                d = rng.standard_normal(hi - lo)
                d -= d.mean()
                for sign in (1.0, -1.0):
                    h[lo:hi] = base * np.exp(sign * s * d)
                    c = _C(h)
                    if c < best_C - 1e-13:
                        best_C = c
                        base = h[lo:hi].copy()
                    else:
                        h[lo:hi] = base
    return h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.2
    rng = np.random.default_rng(424242)

    best_h = None
    best_C = 1e18
    best_p = None

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    # Build polynomial seeds from start at several degrees
    seeds = []
    if start is not None and len(start) >= 8:
        for deg in (7, 9, 11, 13):
            p = _fit_poly(np.asarray(start, dtype=float), deg)
            if p is not None:
                seeds.append(p)
    if not seeds:
        p = np.zeros(9)
        p[0] = 1.26
        seeds.append(p)

    N_coarse = 1500

    def obj_coarse(p):
        return _C(_build_poly(p, N_coarse))

    # Local optimize each seed at coarse N
    results = []
    for seed in seeds:
        if time.process_time() - t0 > deadline * 0.35:
            break
        try:
            res = minimize(obj_coarse, seed, method='Nelder-Mead',
                           options={'xatol': 1e-5, 'fatol': 1e-10, 'maxiter': 1200})
            results.append((res.fun, res.x))
        except Exception:
            pass
    results.sort(key=lambda r: r[0])

    # Progressive refinement at higher N
    for (fun, p) in results[:2]:
        if time.process_time() - t0 > deadline * 0.85:
            break
        cur_p = p.copy()
        cur_fun = fun
        for N_fine, frac in [(3000, 0.55), (6000, 0.75)]:
            if time.process_time() - t0 > deadline * frac:
                break
            def obj_fine(pp, Nf=N_fine):
                return _C(_build_poly(pp, Nf))
            try:
                res = minimize(obj_fine, cur_p, method='Nelder-Mead',
                               options={'xatol': 1e-6, 'fatol': 1e-11, 'maxiter': 1500})
                if res.fun < cur_fun:
                    cur_fun = res.fun
                    cur_p = res.x.copy()
            except Exception:
                pass
        h_cand = _build_poly(cur_p, 6000)
        c_cand = _C(h_cand)
        if c_cand < best_C:
            best_C = c_cand
            best_h = h_cand
            best_p = cur_p.copy()

    # Block polish on best array
    if best_h is not None and time.process_time() - t0 < deadline * 0.95:
        h_pol, c_pol = _block_polish(best_h, deadline * 0.97, t0, rng)
        if c_pol < best_C:
            best_C = c_pol
            best_h = h_pol

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    # Return start if it is still better
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) <= best_C:
            print("C=%.6f (kept start)" % _C(s))
            return s

    print("C=%.6f N=%d" % (best_C, len(best_h)))
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
