def _build(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = np.zeros(N)
    xp = np.ones(N)
    for k in range(len(p)):
        xp = xp * x
        e += p[k] * xp
    e -= e.max()
    return np.exp(e)


def _c_of(p, N):
    return _C(_build(p, N))


def _fit_poly(h0, deg):
    N0 = len(h0)
    x0 = -0.25 + (np.arange(N0) + 0.5) / N0
    mask = h0 > h0.max() * 1e-6
    if mask.sum() < deg + 2:
        return None
    try:
        coef = np.polyfit(x0[mask], np.log(h0[mask]), deg)
    except Exception:
        return None
    p = np.zeros(deg)
    for k in range(1, deg + 1):
        p[k - 1] = coef[deg - k]
    return p


def _shift_poly(p, dN, N):
    """Re-express polynomial p (in x) sampled on N steps as a new polynomial
    fitted on N+dN steps, so the seed transfers between grids."""
    h = _build(p, N)
    return _fit_poly(h, len(p))


def _block_polish(h, best_C, deadline, t0, rng, block=25):
    h = h.copy()
    N = len(h)
    steps = [0.20, 0.10, 0.05, 0.025, 0.012, 0.006, 0.003, 0.0015]
    nblocks = (N + block - 1) // block
    for s in steps:
        if time.process_time() - t0 > deadline:
            break
        improved = False
        order = rng.permutation(nblocks)
        for bi in order:
            if time.process_time() - t0 > deadline:
                break
            lo = bi * block
            hi = min(lo + block, N)
            if hi <= lo:
                continue
            base = h[lo:hi].copy()
            dirs = [np.ones(hi - lo)]
            for _ in range(2):
