            for d in dirs:
                d = d - d.mean()
                for sign in (1.0, -1.0):
                    if time.process_time() - t0 > deadline:
                        break
                    h[lo:hi] = base * np.exp(sign * s * d)
                    c = _C(h)
                    if c < best_C - 1e-14:
                        best_C = c
                        base = h[lo:hi].copy()
                        improved = True
                    else:
                        h[lo:hi] = base
        if not improved and s < 0.005:
            pass
    return h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.2
    rng = np.random.default_rng(20240607)

    best_h = None
    best_C = 1e18
    best_p = None

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    # Recover a high-degree seed from start
    seed = np.zeros(16)
    if start is not None and len(start) >= 10:
        p9 = _fit_poly(np.asarray(start, dtype=float), 9)
        if p9 is not None:
            seed[:9] = p9
            p12 = _fit_poly(np.asarray(start, dtype=float), 12)
            if p12 is not None:
                seed[:12] = p12
    elif start is not None and len(start) >= 6:
        p5 = _fit_poly(np.asarray(start, dtype=float), 5)
        if p5 is not None:
            seed[:5] = p5

    N_coarse = 1200

    seeds = [seed.copy()]
    base_seeds = [
        np.array([1.26, 0.0, 0.0, 0.0, 0.0]),
        np.array([1.0, 2.0, 0.0, 0.0, 0.0]),
        np.array([1.5, -2.0, 0.0, 0.0, 0.0]),
        np.array([1.0, 0.0, 5.0, 0.0, 0.0]),
        np.array([0.5, 3.0, 0.0, -5.0, 0.0]),
        np.array([2.0, 0.0, 0.0, -8.0, 0.0]),
    ]
    for s in base_seeds:
        p = np.zeros(16)
        p[:5] = s
        seeds.append(p)

    def obj(p):
        return _c_of(p, N_coarse)

    best_local = None
    for sd in seeds:
        if time.process_time() - t0 > deadline * 0.35:
            break
        try:
            res = minimize(obj, sd, method='Nelder-Mead',
                           options={'xatol': 1e-5, 'fatol': 1e-9, 'maxiter': 2500})
            if best_local is None or res.fun < best_local.fun:
                best_local = res
        except Exception:
            pass

    if best_local is not None:
        best_p = best_local.x
        h_c = _build(best_p, N_coarse)
        c_c = _C(h_c)
        if c_c < best_C:
            best_C = c_c
            best_h = h_c

    # Multi-resolution Powell / NM refinement
    stages = [(2000, 0.50), (4000, 0.62), (6000, 0.74), (9000, 0.84)]
    for N_fine, frac in stages:
        if best_p is None:
            break
        if time.process_time() - t0 > deadline * frac:
            break
        # Re-seed on new grid
        p_seed = _shift_poly(best_p, 0, N_fine)
        if p_seed is None:
            p_seed = np.zeros_like(best_p)
            p_seed[:len(best_p)] = best_p
        # pad to 16
        p_full = np.zeros(16)
        p_full[:len(p_seed)] = p_seed

        def obj_fine(p, Nf=N_fine):
            return _c_of(p, Nf)

        try:
            res = minimize(obj_fine, p_full, method='Powell',
                           options={'xtol': 1e-6, 'ftol': 1e-11, 'maxiter': 4000})
            if res.fun < best_C:
                best_C = res.fun
                best_p = res.x
                best_h = _build(best_p, N_fine)
        except Exception:
            pass

    # Block polish on the best full array
    if best_h is not None and time.process_time() - t0 < deadline * 0.90:
        h_pol, c_pol = _block_polish(best_h, best_C, deadline * 0.97, t0, rng)
        if c_pol < best_C:
            best_C = c_pol
            best_h = h_pol

    # Final polynomial polish at final resolution
    if best_h is not None and time.process_time() - t0 < deadline:
        N_f = len(best_h)
        p_final = _fit_poly(best_h, 14)
        if p_final is not None:
            def obj_fin(p):
                return _c_of(p, N_f)
            try:
                res = minimize(obj_fin, p_final, method='Nelder-Mead',
                               options={'xatol': 1e-8, 'fatol': 1e-13, 'maxiter': 1200})
                if res.fun < best_C:
                    best_C = res.fun
                    best_h = _build(res.x, N_f)
                    best_p = res.x
            except Exception:
                pass

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) <= best_C:
            return s

    print("C=%.9f N=%d" % (best_C, len(best_h)))
