import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _build(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = np.zeros(N)
    xp = np.ones(N)
    for k in range(1, len(p) + 1):
        xp = xp * x
        e += p[k - 1] * xp
    e -= e.max()
    return np.exp(e)


def _c_of(p, N):
    return _C(_build(p, N))


def _fit_poly(h0, deg):
    N0 = len(h0)
    x0 = -0.25 + (np.arange(N0) + 0.5) / N0
    mask = h0 > h0.max() * 1e-6
    if mask.sum() < deg + 2:
        return None
    try:
        coef = np.polyfit(x0[mask], np.log(h0[mask]), deg)
    except Exception:
        return None
    p = np.zeros(deg)
    for k in range(1, deg + 1):
        p[k - 1] = coef[deg - k]
    return p


def _make_fg(deg, N):
    """Return (f, g) for scipy: f(p)=C, g(p)=dC/dp analytic."""
    x = -0.25 + (np.arange(N) + 0.5) / N
    # precompute powers x^k for k=1..deg  (shape deg x N)
    X = np.empty((deg, N))
    xp = np.ones(N)
    for k in range(deg):
        xp = xp * x
        X[k] = xp

    def fg(p):
        e = p @ X
        e = e - e.max()
        h = np.exp(e)
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(deg)
        conv = np.convolve(h, h)
        M = conv.max()
        m = int(np.argmax(conv))
        # gradient pieces
        # term1: 4N/s^2 * sum_i h_i h_{m-i} (x_i^k - wmean_k)
        # term2: -4N M/s^3 * sum_i h_i (x_i^k - wmean_k)
        # where wmean_k = sum_i h_i x_i^k / s
        # combine: define a_i = h_i h_{m-i} (for valid i), b_i = h_i
        # and wmean_k = (b . X_k)/s
        # dC/dp_k = 4N/s^2 * [ (a . X_k) - (a.sum())*(b.X_k)/s ]
        #          - 4N M/s^3 * [ (b . X_k) - s*(b.X_k)/s ]
        #          = 4N/s^2 * [ (a . X_k) - (a.sum())*(b.X_k)/s ]
        #          (second term vanishes!)
        # Wait: sum_i h_i (x_i^k - wmean_k) = (b.X_k) - s*wmean_k = 0.
        # So term2 is zero. Good — but the problem statement includes it;
        # it's identically zero. Keep formula consistent.
        # Build a_i = h_i * h_{m-i} for i in [m-N+1, m] intersect [0,N-1]
        a = np.zeros(N)
        lo = max(0, m - (N - 1))
        hi = min(N - 1, m)
        if hi >= lo:
            ii = np.arange(lo, hi + 1)
            a[ii] = h[ii] * h[m - ii]
        aX = a @ X  # length deg
        bX = h @ X  # length deg
        asum = a.sum()
        g = (4.0 * N / (s * s)) * (aX - asum * bX / s)
        Cval = 2.0 * N * M / (s * s)
        return Cval, g

    return fg


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5

    best_h = None
    best_C = 1e18
    best_p = None

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    deg = 24
    seed = np.zeros(deg)
    if start is not None and len(start) >= 10:
        p24 = _fit_poly(np.asarray(start, dtype=float), deg)
        if p24 is not None:
            seed = p24
    elif start is not None and len(start) >= 8:
        p5 = _fit_poly(np.asarray(start, dtype=float), 5)
        if p5 is not None:
            seed[:5] = p5

    # L-BFGS-B at N=6000
    if time.process_time() - t0 < deadline * 0.55:
        N1 = 6000
        fg1 = _make_fg(deg, N1)
        try:
            res = minimize(fg1, seed, jac=True, method='L-BFGS-B',
                           options={'ftol': 1e-12, 'gtol': 1e-12, 'maxiter': 500})
            if res.fun < best_C:
                best_p = res.x
                best_h = _build(best_p, N1)
                best_C = _C(best_h)
        except Exception:
            pass

    # L-BFGS-B at N=9000
    if best_p is not None and time.process_time() - t0 < deadline:
        N2 = 9000
        fg2 = _make_fg(deg, N2)
        try:
            res = minimize(fg2, best_p, jac=True, method='L-BFGS-B',
                           options={'ftol': 1e-12, 'gtol': 1e-12, 'maxiter': 500})
            if res.fun < best_C:
                best_p = res.x
                best_h = _build(best_p, N2)
                best_C = _C(best_h)
        except Exception:
            pass

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) <= best_C:
            return s

    print("C=%.6f deg=%d" % (best_C, deg))
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _build(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = np.zeros(N)
    xp = np.ones(N)
    for k in range(len(p)):
        xp = xp * x
        e += p[k] * xp
    e -= e.max()
    return np.exp(e)


def _c_of(p, N):
    return _C(_build(p, N))


def _fit_poly(h0, deg):
    N0 = len(h0)
    x0 = -0.25 + (np.arange(N0) + 0.5) / N0
    mask = h0 > h0.max() * 1e-6
    if mask.sum() < deg + 2:
        return None
    try:
        coef = np.polyfit(x0[mask], np.log(h0[mask]), deg)
    except Exception:
        return None
    p = np.zeros(deg)
    for k in range(1, deg + 1):
        p[k - 1] = coef[deg - k]
    return p


def _resample(h, N):
    """Resample heights h (uniform on its grid) onto N uniform steps."""
    M = len(h)
    if M == N:
        return h.copy()
    x = (np.arange(N) + 0.5) / N  # in [0,1]
    xp = (np.arange(M) + 0.5) / M
    return np.interp(x, xp, h)


def _block_polish(h, deadline, t0, rng, block=30):
    h = h.copy()
    N = len(h)
    best_C = _C(h)
    steps = [0.1, 0.05, 0.025, 0.012, 0.006, 0.003, 0.0015]
    nblocks = (N + block - 1) // block
    for s in steps:
        if time.process_time() - t0 > deadline:
            break
        for bi in rng.permutation(nblocks):
            if time.process_time() - t0 > deadline:
                break
            lo = bi * block
            hi = min(lo + block, N)
            if hi <= lo:
                continue
            base = h[lo:hi].copy()
            for _ in range(2):
                d = rng.standard_normal(hi - lo)
                d = d - d.mean()
                for sign in (1.0, -1.0):
                    h[lo:hi] = base * np.exp(sign * s * d)
                    c = _C(h)
                    if c < best_C - 1e-13:
                        best_C = c
                        base = h[lo:hi].copy()
                    else:
                        h[lo:hi] = base
    return h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5
    rng = np.random.default_rng(12345)

    best_h = None
    best_C = 1e18
    best_p = None

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    # Recover a polynomial seed from start (deg 9) and extend to 16.
    seed = np.zeros(16)
    if start is not None and len(start) >= 10:
        p9 = _fit_poly(np.asarray(start, dtype=float), 9)
        if p9 is not None:
            seed[:9] = p9
    elif start is not None and len(start) >= 8:
        p5 = _fit_poly(np.asarray(start, dtype=float), 5)
        if p5 is not None:
            seed[:5] = p5

    N_coarse = 1500

    seeds = [seed.copy()]
    base_seeds = [
        np.array([1.26, 0.0, 0.0, 0.0, 0.0]),
        np.array([1.0, 2.0, 0.0, 0.0, 0.0]),
        np.array([1.5, -2.0, 0.0, 0.0, 0.0]),
        np.array([1.0, 0.0, 5.0, 0.0, 0.0]),
        np.array([0.5, 3.0, 0.0, -5.0, 0.0]),
        np.array([2.0, 0.0, 0.0, -8.0, 0.0]),
        np.array([1.3, 0.0, 0.0, 0.0, 4.0]),
    ]
    for s in base_seeds:
        p = np.zeros(16)
        p[:5] = s
        seeds.append(p)

    def obj(p):
        return _c_of(p, N_coarse)

    best_local = None
    for sd in seeds:
        if time.process_time() - t0 > deadline * 0.40:
            break
        try:
            res = minimize(obj, sd, method='Nelder-Mead',
                           options={'xatol': 1e-5, 'fatol': 1e-9, 'maxiter': 3000})
            if best_local is None or res.fun < best_local.fun:
                best_local = res
        except Exception:
            pass

    if best_local is not None:
        best_p = best_local.x
        h_c = _build(best_p, N_coarse)
        c_c = _C(h_c)
        if c_c < best_C:
            best_C = c_c
            best_h = h_c

    # Refine polynomial at increasing N
    for N_fine, frac in [(3000, 0.55), (6000, 0.70)]:
        if best_p is not None and time.process_time() - t0 < deadline * frac:
            def obj_fine(p, Nf=N_fine):
                return _c_of(p, Nf)
            try:
                res = minimize(obj_fine, best_p, method='Nelder-Mead',
                               options={'xatol': 1e-6, 'fatol': 1e-11, 'maxiter': 2500})
                if res.fun < best_C:
                    best_p = res.x
                    best_h = _build(best_p, N_fine)
                    best_C = res.fun
            except Exception:
                pass

    # If polynomial best exists, resample to a higher N for direct block polish.
    if best_p is not None:
        N_top = 6000
        h_top = _build(best_p, N_top)
        c_top = _C(h_top)
        if c_top < best_C:
            best_C = c_top
            best_h = h_top

    # Direct block polish on the array (this is the key improvement:
    # it can escape the polynomial family and squeeze the array locally).
    if best_h is not None and time.process_time() - t0 < deadline * 0.90:
        h_pol, c_pol = _block_polish(np.asarray(best_h, float), deadline * 0.95, t0, rng)
        if c_pol < best_C:
            best_C = c_pol
            best_h = h_pol

    # Final polish with smaller blocks/steps if time remains.
    if best_h is not None and time.process_time() - t0 < deadline * 0.97:
        h_pol, c_pol = _block_polish(np.asarray(best_h, float), deadline, t0, rng, block=15)
        if c_pol < best_C:
            best_C = c_pol
            best_h = h_pol

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) <= best_C:
            return s

    print("C=%.6f N=%d" % (best_C, len(best_h)))
    return np.asarray(best_h, dtype=float)

