    p = np.zeros(deg)
    for k in range(1, deg + 1):
        p[k - 1] = coef[deg - k]
    return p


def _C_fft(h):
    # cheaper approximate max of convolution via FFT (for coarse stages)
    N = len(h)
    L = 1
    while L < 2 * N:
        L *= 2
    H = np.fft.rfft(h, L)
    conv = np.fft.irfft(H * H, L)
    m = np.max(conv)
    s = h.sum()
    return 2.0 * N * m / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 2.0

    best_h = None
    best_C = 1e18
