import numpy as np
import time
from scipy.optimize import minimize, minimize_scalar
from scipy.signal import fftconvolve


def _conv(h):
    if len(h) > 2000:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(_conv(h)) / (s * s)


def _C_grad_u(u):
    h = np.exp(u)
    N = len(h)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (s * s)
    dM = np.zeros(N)
    idx = m - np.arange(N)
    valid = (idx >= 0) & (idx < N)
    dM[valid] = 2.0 * h[idx[valid]]
    dC_dh = 2.0 * N / (s * s) * dM - 4.0 * N * M / (s * s * s)
    return C, h * dC_dh


def _resample(h, N_new):
    N_old = len(h)
    x_old = (np.arange(N_old) + 0.5) / N_old
    x_new = (np.arange(N_new) + 0.5) / N_new
    return np.interp(x_new, x_old, h)


def _opt_u(h_init, maxiter, deadline):
    h_init = np.maximum(h_init, 1e-12)
    u0 = np.log(h_init)
    u0 -= u0.max()

    def fun(u):
        return _C_grad_u(u)

    try:
        res = minimize(fun, u0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-15, 'gtol': 1e-12})
        u = res.x
    except Exception:
        u = u0
    h = np.exp(u)
    return h, _C(h)


def _active_refine(h, deadline, rounds=60):
    h = h.copy()
    N = len(h)
    best_C = _C(h)
    for _ in range(rounds):
        if time.process_time() > deadline:
            break
        conv = _conv(h)
        M = conv.max()
        active = np.where(conv > M * (1 - 1e-9))[0]
        improved = False
        for m in active[:8]:
            lo = max(0, m - N + 1)
            hi = min(N - 1, m)
            if hi < lo:
                continue
            a = lo
            b = hi
            seg = h[a:b + 1].copy()
            if seg.sum() <= 0:
                continue
            base = seg.copy()

            def f(alpha):
                newh = h.copy()
                newh[a:b + 1] = base * (1.0 + alpha * np.linspace(-1, 1, b - a + 1))
                return _C(newh)

            try:
                r = minimize_scalar(f, bounds=(-0.05, 0.05), method='bounded',
                                    options={'xatol': 1e-6})
                if r.fun < best_C - 1e-12:
                    newh = h.copy()
                    newh[a:b + 1] = base * (1.0 + r.x * np.linspace(-1, 1, b - a + 1))
                    h = newh
                    best_C = r.fun
                    improved = True
            except Exception:
                pass
        if not improved:
            break
    return h, best_C


def _coord_sweep(h, deadline, sweeps=200):
    """Multiplicative coordinate sweep on near-max knots of f*f."""
    h = h.copy()
    N = len(h)
    best_C = _C(h)
    delta0 = 0.05
    for k in range(sweeps):
        if time.process_time() > deadline:
            break
        delta = delta0 * (0.5 ** (k // 40))
        if delta < 1e-4:
            delta = 1e-4
        conv = _conv(h)
        M = conv.max()
        active = np.where(conv > 0.995 * M)[0]
        if len(active) == 0:
            break
        # map knots to contributing indices
        idxs = set()
        for m in active:
            lo = max(0, m - N + 1)
            hi = min(N - 1, m)
            for i in range(lo, hi + 1):
                idxs.add(i)
        idxs = sorted(idxs)
        improved = False
        for i in idxs:
            if time.process_time() > deadline:
                break
            old = h[i]
            if old <= 0:
                continue
            for sign in (1.0, -1.0):
                h[i] = old * np.exp(sign * delta)
                c = _C(h)
                if c < best_C - 1e-14:
                    best_C = c
                    old = h[i]
                    improved = True
                else:
                    h[i] = old
        if not improved and delta <= 1e-4:
            break
    return h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5

    best_h = None
    best_C = 1e18

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    if best_h is None:
        best_h = np.ones(50)
        best_C = _C(best_h)

    # Stage 1: coarse optimize in log-space
    N1 = 1500
    h1 = _resample(best_h, N1)
    h1, c1 = _opt_u(h1, maxiter=400, deadline=deadline)
    if c1 < best_C:
        best_C = c1
        best_h = h1
    print("stage1 N=%d C=%.6f t=%.2f" % (N1, c1, time.process_time() - t0))

    # Stage 2: active-set local refinement at N=1500
    if time.process_time() - t0 < deadline * 0.5:
        h1b, c1b = _active_refine(best_h, deadline * 0.55)
        if c1b < best_C:
            best_C = c1b
            best_h = h1b
        print("stage2 act C=%.6f t=%.2f" % (c1b, time.process_time() - t0))

    # Stage 3: upsample and log-space optimize at N=12000
    if time.process_time() - t0 < deadline:
        N2 = 12000
        h2 = _resample(best_h, N2)
        h2, c2 = _opt_u(h2, maxiter=60, deadline=deadline)
        if c2 < best_C:
            best_C = c2
            best_h = h2
        print("stage3 N=%d C=%.6f t=%.2f" % (N2, c2, time.process_time() - t0))

    # Stage 4: active-set refinement at N=12000
    if time.process_time() - t0 < deadline and len(best_h) == 12000:
        h4, c4 = _active_refine(best_h, deadline, rounds=40)
        if c4 < best_C:
            best_C = c4
            best_h = h4
        print("stage4 act C=%.6f t=%.2f" % (c4, time.process_time() - t0))

    # Stage 5: final short L-BFGS polish
    if time.process_time() - t0 < deadline:
        h5, c5 = _opt_u(best_h, maxiter=20, deadline=deadline)
        if c5 < best_C:
            best_C = c5
            best_h = h5
        print("stage5 C=%.6f t=%.2f" % (c5, time.process_time() - t0))

    # Stage 6: multiplicative coordinate sweep on near-max knots
    if time.process_time() - t0 < deadline:
        h6, c6 = _coord_sweep(best_h, deadline, sweeps=200)
        if c6 < best_C:
            best_C = c6
            best_h = h6
        print("stage6 coord C=%.6f t=%.2f" % (c6, time.process_time() - t0))

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) <= best_C:
            return s

    print("final C=%.6f N=%d" % (best_C, len(best_h)))
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _build(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = np.zeros(N)
    xp = np.ones(N)
    for k in range(1, len(p) + 1):
        xp = xp * x
        e += p[k - 1] * xp
    e -= e.max()
    return np.exp(e)


def _fit_poly(h0, deg):
    N0 = len(h0)
    x0 = -0.25 + (np.arange(N0) + 0.5) / N0
    mask = h0 > h0.max() * 1e-6
    if mask.sum() < deg + 2:
        return None
    try:
        coef = np.polyfit(x0[mask], np.log(h0[mask]), deg)
    except Exception:
        return None
    p = np.zeros(deg)
    for k in range(1, deg + 1):
        p[k - 1] = coef[deg - k]
    return p


def _C_fft(h):
    N = len(h)
    L = 1
    while L < 2 * N:
        L *= 2
    H = np.fft.rfft(h, L)
    conv = np.fft.irfft(H * H, L)
    m = np.max(conv)
    s = h.sum()
    return 2.0 * N * m / (s * s)


def _refine_logspace(h, maxiter, t0, deadline):
    """Free-height log-space L-BFGS-B refinement."""
    h = np.asarray(h, dtype=float)
    N = len(h)
    s0 = h.sum()
    x0 = np.log(h + 1e-12)

    def obj(x):
        hh = np.exp(x)
        return _C_fft(hh)

    try:
        res = minimize(obj, x0, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'ftol': 1e-12,
                                'maxcor': 20})
        hh = np.exp(res.x)
        s = hh.sum()
        if s > 0:
            hh = hh * (s0 / s)
        return hh
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 2.0

    best_h = None
    best_C = 1e18
    best_p = None

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    N_coarse = 1000
    seeds = []
    if start is not None:
        s0 = np.asarray(start, dtype=float)
        for deg in (14, 12, 10, 9, 8, 6, 5):
            if len(s0) >= deg + 2:
                pd = _fit_poly(s0, deg)
                if pd is not None:
                    p = np.zeros(20)
                    m = min(deg, 20)
                    p[:m] = pd[:m]
                    seeds.append(p)

    base_seeds = [
        np.array([1.26, 0.0, 0.0, 0.0, 0.0]),
        np.array([1.0, 2.0, 0.0, 0.0, 0.0]),
        np.array([1.5, -2.0, 0.0, 0.0, 0.0]),
        np.array([1.0, 0.0, 5.0, 0.0, 0.0]),
        np.array([0.5, 3.0, 0.0, -5.0, 0.0]),
        np.array([2.0, 0.0, 0.0, -8.0, 0.0]),
        np.array([1.3, 0.0, 0.0, 0.0, 4.0]),
    ]
    for s in base_seeds:
        p = np.zeros(20)
        p[:5] = s
        seeds.append(p)

    def obj(p):
        return _C(_build(p, N_coarse))

    scored = []
    for sd in seeds:
        try:
            c = obj(sd)
            scored.append((c, sd))
        except Exception:
            pass
    scored.sort(key=lambda t: t[0])

    best_local = None
    n_seed_opt = min(len(scored), 5)
    for i in range(n_seed_opt):
        if time.process_time() - t0 > deadline * 0.35:
            break
        sd = scored[i][1]
        try:
            res = minimize(obj, sd, method='Nelder-Mead',
                           options={'xatol': 1e-5, 'fatol': 1e-10, 'maxiter': 4000})
            if best_local is None or res.fun < best_local.fun:
                best_local = res
        except Exception:
            pass

    if best_local is not None:
        best_p = best_local.x
        h_c = _build(best_p, N_coarse)
        c_c = _C(h_c)
        if c_c < best_C:
            best_C = c_c
            best_h = h_c

    stages = [(2000, 0.50, 3000), (4000, 0.68, 2500),
              (6000, 0.82, 2000), (8000, 0.93, 1500), (10000, 1.0, 1000)]
    if best_p is not None:
        for (N, frac, iters) in stages:
            if time.process_time() - t0 > deadline * frac:
                continue
            def objN(p, N=N):
                return _C(_build(p, N))
            try:
                res = minimize(objN, best_p, method='Nelder-Mead',
                               options={'xatol': 1e-7, 'fatol': 1e-12,
                                        'maxiter': iters})
                if res.fun < best_C:
                    best_p = res.x
                    best_h = _build(best_p, N)
                    best_C = res.fun
            except Exception:
                pass

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    # --- Experiment: free-height log-space L-BFGS-B refinement ---
    # Stage 1: refine at current N
    if time.process_time() - t0 < deadline - 1.0:
        h_ref = _refine_logspace(best_h, 300, t0, deadline)
        c_ref = _C(h_ref)
        if c_ref < best_C:
            best_h = h_ref
            best_C = c_ref
            print("logspace N=%d C=%.6f" % (len(best_h), best_C))

    # Stage 2: upsample to N=12000 and refine once more
    if time.process_time() - t0 < deadline - 1.0:
        N2 = 12000
        h_up = np.interp(
            -0.25 + (np.arange(N2) + 0.5) / N2,
            -0.25 + (np.arange(len(best_h)) + 0.5) / len(best_h),
            best_h)
        h_up = np.maximum(h_up, 0.0)
        c_up = _C(h_up)
        if c_up < best_C:
            best_h = h_up
            best_C = c_up
        if time.process_time() - t0 < deadline - 0.5:
            h_ref2 = _refine_logspace(best_h, 150, t0, deadline)
            c_ref2 = _C(h_ref2)
            if c_ref2 < best_C:
                best_h = h_ref2
                best_C = c_ref2
                print("logspace N=%d C=%.6f" % (len(best_h), best_C))

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) <= best_C:
            return s

    print("C=%.6f N=%d" % (best_C, len(best_h)))
    return np.asarray(best_h, dtype=float)

