    if s <= 0:
        return 1e18
    N = len(h)
    if N >= 2000:
        L = 1
        while L < 2 * N:
            L *= 2
        H = np.fft.rfft(h, L)
        conv = np.fft.irfft(H * H, L)
        return 2.0 * N * np.max(conv[:2 * N - 1]) / (s * s)
    return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)


def _build(p, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    e = np.zeros(N)
    xp = np.ones(N)
    for k in range(1, len(p) + 1):
        xp = xp * x
        e += p[k - 1] * xp
    e -= e.max()
    return np.exp(e)


def _fit_poly(h0, deg):
    N0 = len(h0)
    x0 = -0.25 + (np.arange(N0) + 0.5) / N0
    mask = h0 > h0.max() * 1e-6
    if mask.sum() < deg + 2:
        return None
    try:
        coef = np.polyfit(x0[mask], np.log(h0[mask]), deg)
    except Exception:
        return None
    p = np.zeros(deg)
    for k in range(1, deg + 1):
        p[k - 1] = coef[deg - k]
    return p


def _make_fg(deg, N):
    x = -0.25 + (np.arange(N) + 0.5) / N
    X = np.empty((deg, N))
    xp = np.ones(N)
    for k in range(deg):
        xp = xp * x
        X[k] = xp

    def fg(p):
        e = p @ X
        e = e - e.max()
        h = np.exp(e)
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(deg)
        L = 1
        while L < 2 * N:
            L *= 2
        H = np.fft.rfft(h, L)
        conv = np.fft.irfft(H * H, L)[:2 * N - 1]
        M = conv.max()
        m = int(np.argmax(conv))
        a = np.zeros(N)
        lo = max(0, m - (N - 1))
        hi = min(N - 1, m)
        if hi >= lo:
            ii = np.arange(lo, hi + 1)
            a[ii] = h[ii] * h[m - ii]
        aX = a @ X
        bX = h @ X
        asum = a.sum()
        g = (4.0 * N / (s * s)) * (aX - asum * bX / s)
        Cval = 2.0 * N * M / (s * s)
        return Cval, g

    return fg


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5

    best_h = None
    best_C = 1e18
    best_p = None

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    # Fit a bank of polynomial seeds from start at several degrees.
    seeds = []
    if start is not None:
        s0 = np.asarray(start, dtype=float)
        for deg in (24, 18, 14, 12, 10):
            if len(s0) >= deg + 2:
                pd = _fit_poly(s0, deg)
                if pd is not None:
                    seeds.append((deg, pd))

    # Optimize the best-fit seed at moderate N with analytic gradient,
    # then attempt to increase degree by refitting and re-optimizing.
    def run_lbfgs(deg, p_seed, N, maxiter=800):
        fg = _make_fg(deg, N)
        try:
            res = minimize(fg, p_seed, jac=True, method='L-BFGS-B',
                           options={'ftol': 1e-13, 'gtol': 1e-13,
                                    'maxiter': maxiter})
            return res
        except Exception:
            return None

    # Coarse pass: try each seed at small N, keep the best.
    N0 = 3000
    scored = []
    for (deg, pd) in seeds:
        p = np.zeros(deg)
        p[:len(pd)] = pd[:deg]
        c = _C(_build(p, N0))
        scored.append((c, deg, p))
    scored.sort(key=lambda t: t[0])

    for (c0, deg, p) in scored[:2]:
        if time.process_time() - t0 > deadline * 0.45:
            break
        res = run_lbfgs(deg, p, N0)
        if res is not None:
            h = _build(res.x, N0)
            cc = _C(h)
            if cc < best_C:
                best_C = cc
                best_h = h
                best_p = res.x.copy()
                best_deg = deg

    if best_p is None:
        # Fall back to any seed
        if scored:
            _, deg, p = scored[0]
            best_p = p
            best_deg = deg
        else:
            best_deg = 10
            best_p = np.zeros(best_deg)
            best_p[0] = 1.0

    # Degree escalation: refit best solution with higher-degree polynomial,
    # re-optimize at growing N.
    stages = [(6000, 0.60, 1000), (9000, 0.78, 1000), (12000, 0.92, 800)]
    for (N, frac, iters) in stages:
        if time.process_time() - t0 > deadline * frac:
            continue
        # Try to grow degree
        h_cur = _build(best_p, N)
        try_deg = min(best_deg + 6, 30)
        pd = _fit_poly(h_cur, try_deg)
        if pd is not None:
            cand_p = pd
            cand_deg = try_deg
        else:
            cand_p = best_p
            cand_deg = best_deg
        res = run_lbfgs(cand_deg, cand_p, N, maxiter=iters)
        if res is not None:
            h = _build(res.x, N)
            cc = _C(h)
            if cc < best_C:
                best_C = cc
                best_h = h
                best_p = res.x.copy()
                best_deg = cand_deg
        # Also try current degree in case growing hurt
        if cand_deg != best_deg:
            res = run_lbfgs(best_deg, best_p, N, maxiter=iters)
            if res is not None:
                h = _build(res.x, N)
                cc = _C(h)
                if cc < best_C:
                    best_C = cc
                    best_h = h
                    best_p = res.x.copy()

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) <= best_C:
            return s

