    if N <= 2000:
        return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)
    L = 1
    while L < 2 * N:
        L *= 2
    H = np.fft.rfft(h, L)
    conv = np.fft.irfft(H * H, L)
    return 2.0 * N * np.max(conv) / (s * s)


def _full_from_half(u):
    e = np.exp(u)
    return np.concatenate([e, e[::-1]])


def _C_grad_u_half(u, beta=None):
    h = _full_from_half(u)
    N = len(h)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(len(u))
    conv = np.convolve(h, h)
    if beta is None:
        m = int(np.argmax(conv))
        M = conv[m]
        dM = np.zeros(N)
        idx = m - np.arange(N)
        valid = (idx >= 0) & (idx < N)
        dM[valid] = 2.0 * h[idx[valid]]
    else:
        bconv = beta * conv
        mx = bconv.max()
        e = np.exp(bconv - mx)
        Z = e.sum()
        M = (mx + np.log(Z)) / beta
        w = e / Z
        corr_full = np.correlate(h, w, 'full')
        dM = 2.0 * corr_full[N - 1 - np.arange(N)]
    C = 2.0 * N * M / (s * s)
    dC_dh = 2.0 * N / (s * s) * dM - 4.0 * N * M / (s * s * s)
    dC_du_full = h * dC_dh
    nh = len(u)
    dC_du_half = dC_du_full[:nh] + dC_du_full[::-1][:nh]
    return C, dC_du_half


