    if s <= 0:
        return 1e18, np.zeros(N)
    conv = _conv_full(h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (s * s)
    dM = np.zeros(N)
    idx = m - np.arange(N)
    valid = (idx >= 0) & (idx < N)
    dM[valid] = 2.0 * h[idx[valid]]
    dC_dh = 2.0 * N / (s * s) * dM - 4.0 * N * M / (s * s * s)
    return C, h * dC_dh


def _C_grad_u_smooth(u, eps):
    h = np.exp(u - u.max())
    N = len(h)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(N)
    conv = _conv_full(h)
    Mmax = conv.max()

    sel = np.nonzero(conv >= Mmax * (1.0 - eps))[0]
    if sel.size == 0:
        sel = np.array([int(np.argmax(conv))])
    w = np.zeros(conv.size)
    w[sel] = 1.0 / sel.size

    C = 2.0 * N * Mmax / (s * s)
    corr_full = np.correlate(h, w, 'full')
    dM = 2.0 * corr_full[N - 1 - np.arange(N)]
    dC_dh = 2.0 * N / (s * s) * dM - 4.0 * N * Mmax / (s * s * s)
    return C, h * dC_dh


def _resample(h, N_new):
    N_old = len(h)
    x_old = (np.arange(N_old) + 0.5) / N_old
    x_new = (np.arange(N_new) + 0.5) / N_new
    return np.interp(x_new, x_old, h)


def _opt(h_init, maxiter, eps, deadline, t0):
    N = len(h_init)
    h_init = np.maximum(h_init, 1e-12)
    u0 = np.log(h_init)
    u0 -= u0.max()
    if eps is None:
        fun = _C_grad_u
    else:
        def fun(u):
            return _C_grad_u_smooth(u, eps)
    try:
        res = minimize(fun, u0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-15, 'gtol': 1e-11},
                       callback=lambda xk: time.process_time() - t0 > deadline)
        u = res.x
    except Exception:
        u = u0
    h = np.exp(u - u.max())
    return h, _C(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5

    best_h = None
    best_C = 1e18

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    if best_h is None:
        best_h = np.ones(50)
        best_C = _C(best_h)

    N_work = 9000
    if len(best_h) >= N_work:
        N_work = len(best_h)
    h = _resample(best_h, N_work)
    h = np.maximum(h, 1e-12)
    h = h / h.max()

    epss = [1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5, 1e-6]
    for eps in epss:
        if time.process_time() - t0 > deadline * 0.8:
            break
        h, c = _opt(h, maxiter=120, eps=eps, deadline=deadline * 0.85, t0=t0)
        if c < best_C:
            best_C = c
            best_h = h.copy()
        print("eps=%.0e C=%.6f t=%.2f" % (eps, c, time.process_time() - t0))

    if time.process_time() - t0 < deadline:
        h, c = _opt(h, maxiter=200, eps=None, deadline=deadline, t0=t0)
        if c < best_C:
            best_C = c
            best_h = h.copy()
        print("hard C=%.6f t=%.2f" % (c, time.process_time() - t0))

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) <= best_C:
            print("returning start C=%.6f" % _C(s))
            return s

    print("final C=%.6f N=%d" % (best_C, len(best_h)))
    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    N = len(h)
    if N <= 2000:
        return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)
    L = 1
    while L < 2 * N:
        L *= 2
    H = np.fft.rfft(h, L)
    conv = np.fft.irfft(H * H, L)
    return 2.0 * N * np.max(conv) / (s * s)


def _conv_full(h):
    N = len(h)
    L = 1
    while L < 2 * N:
        L *= 2
    H = np.fft.rfft(h, L)
    c = np.fft.irfft(H * H, L)
    return c[:2 * N - 1]


def _C_grad_u(u):
    h = np.exp(u - u.max())
    N = len(h)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(N)
    conv = _conv_full(h)
    m = int(np.argmax(conv))
    M = conv[m]
    C = 2.0 * N * M / (s * s)
    dM = np.zeros(N)
    idx = m - np.arange(N)
    valid = (idx >= 0) & (idx < N)
    dM[valid] = 2.0 * h[idx[valid]]
    dC_dh = 2.0 * N / (s * s) * dM - 4.0 * N * M / (s * s * s)
    return C, h * dC_dh


def _C_grad_u_smooth(u, beta):
    h = np.exp(u - u.max())
    N = len(h)
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(N)
    conv = _conv_full(h)
    bconv = beta * conv
    mx = bconv.max()
    e = np.exp(bconv - mx)
    Z = e.sum()
    M = (mx + np.log(Z)) / beta
    w = e / Z
    C = 2.0 * N * M / (s * s)
    corr_full = np.correlate(h, w, 'full')
    dM = 2.0 * corr_full[N - 1 - np.arange(N)]
    dC_dh = 2.0 * N / (s * s) * dM - 4.0 * N * M / (s * s * s)
    return C, h * dC_dh


def _resample(h, N_new):
    N_old = len(h)
    if N_old == N_new:
        return h.copy()
    x_old = (np.arange(N_old) + 0.5) / N_old
    x_new = (np.arange(N_new) + 0.5) / N_new
    return np.interp(x_new, x_old, h)


def _opt(h_init, maxiter, beta, deadline, t0):
    h_init = np.maximum(h_init, 1e-12)
    u0 = np.log(h_init)
    u0 -= u0.max()
    if beta is None:
        fun = _C_grad_u
    else:
        def fun(u):
            return _C_grad_u_smooth(u, beta)
    try:
        res = minimize(fun, u0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-15, 'gtol': 1e-11},
                       callback=lambda xk: time.process_time() - t0 > deadline)
        u = res.x
    except Exception:
        u = u0
    h = np.exp(u - u.max())
    return h, _C(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.2

    best_h = None
    best_C = 1e18

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.size > 0 and h0.sum() > 0:
            best_h = h0.copy()
            best_C = _C(h0)

    if best_h is None:
        best_h = np.ones(50)
        best_C = _C(best_h)

    # Upsample to higher resolution to add degrees of freedom.
    N_work = max(len(best_h), 24000)
    h = _resample(best_h, N_work)
    h = np.maximum(h, 1e-12)
    h = h / h.max()

    betas = [3e3, 1e4, 3e4, 1e5, 3e5, 1e6, 3e6, 1e7, 3e7]
    for beta in betas:
        if time.process_time() - t0 > deadline * 0.85:
            break
        h, c = _opt(h, maxiter=350, beta=beta, deadline=deadline * 0.85, t0=t0)
        if c < best_C:
            best_C = c
            best_h = h.copy()
        print("beta=%g C=%.6f t=%.2f" % (beta, c, time.process_time() - t0))

    if time.process_time() - t0 < deadline:
        h, c = _opt(best_h, maxiter=2000, beta=None,
                    deadline=deadline, t0=t0)
        if c < best_C:
            best_C = c
            best_h = h.copy()
        print("hard C=%.6f t=%.2f" % (c, time.process_time() - t0))

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) <= best_C:
            print("returning start C=%.6f" % _C(s))
            return s

    print("final C=%.6f N=%d" % (best_C, len(best_h)))
    return np.asarray(best_h, dtype=float)
